--

CREATE FUNCTION "public"."_control2_active_game_session"("p_game_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT a.session_id FROM public.game_session_active a
  JOIN public.game_sessions s ON s.id = a.session_id AND s.game_id = a.game_id
  WHERE a.game_id = p_game_id AND s.control_version = 2 AND s.ended_at IS NULL
  LIMIT 1
$$;


--
-- Name: _control2_device_event_view("text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_device_event_view"("p_device_type" "text", "p_event_type" "text", "d" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'category', CASE
      WHEN p_event_type = 'lease_state' THEN 'device_lease'
      WHEN p_event_type = 'transport_state' THEN 'device_transport'
      WHEN p_event_type = 'state_sync' THEN 'device_state_sync'
      WHEN p_event_type = 'network_state' AND d->>'source' = 'probe' THEN 'device_network'
      WHEN p_event_type = 'page_lifecycle' THEN 'page_lifecycle'
      WHEN p_event_type = 'wake_lock' THEN 'wake_lock'
      WHEN p_event_type = 'device_info' THEN 'device_info'
      ELSE 'display_state' END,
    'message', CASE
      WHEN p_event_type = 'page_state' THEN
        'Stan karty ' || CASE p_device_type
          WHEN 'display' THEN 'Wyświetlacz' WHEN 'host' THEN 'Host' WHEN 'buzzer' THEN 'Buzzer'
          WHEN 'control' THEN 'Control' ELSE 'urządzenia' END || ': ' ||
        CASE d->>'visibility' WHEN 'visible' THEN 'widoczna' WHEN 'hidden' THEN 'w tle' ELSE 'nieznana' END ||
        CASE d->>'visibility_reason' WHEN 'initial' THEN ' (stan początkowy).'
          WHEN 'visibilitychange' THEN ' (zmiana widoczności).' ELSE '.' END
      WHEN p_event_type = 'network_state' AND d->>'source' = 'probe' THEN CASE
        WHEN d->>'phase' = 'baseline' THEN 'Pomiar łącza na starcie gry.'
        WHEN d->>'phase' = 'slow' AND d->>'verdict' = 'device_network' THEN 'Wolne łącze urządzenia (już do Cloudflare).'
        WHEN d->>'phase' = 'slow' AND d->>'verdict' = 'server' THEN 'Wolna odpowiedź serwera przy sprawnym łączu urządzenia.'
        WHEN d->>'phase' = 'recovered' THEN 'Łącze i odpowiedź serwera wróciły do normy.'
        ELSE 'Pomiar łącza.' END
      WHEN p_event_type = 'page_lifecycle' THEN CASE d->>'phase'
        WHEN 'freeze' THEN 'Przeglądarka zamroziła stronę.'
        WHEN 'resume' THEN 'Strona wznowiona po zamrożeniu.'
        WHEN 'pagehide' THEN 'Strona zamknięta lub przeładowana.'
        WHEN 'pageshow' THEN 'Strona przywrócona z pamięci przeglądarki.'
        WHEN 'offline' THEN 'Przeglądarka zgłosiła brak sieci.'
        WHEN 'online' THEN 'Przeglądarka zgłosiła powrót sieci.'
        ELSE 'Zmiana stanu strony.' END
      WHEN p_event_type = 'wake_lock' THEN CASE d->>'phase'
        WHEN 'granted' THEN 'Blokada wygaszania ekranu włączona.'
        WHEN 'denied' THEN 'Przeglądarka odmówiła blokady wygaszania ekranu.'
        WHEN 'unsupported' THEN 'Przeglądarka nie obsługuje blokady wygaszania ekranu.'
        WHEN 'released' THEN 'System zwolnił blokadę wygaszania ekranu.'
        ELSE 'Blokada wygaszania ekranu.' END
      WHEN p_event_type = 'device_info' THEN 'Urządzenie i przeglądarka.'
      WHEN p_event_type = 'lease_state' AND d->>'to_state' = 'waiting' THEN 'Urządzenie oczekuje na zwolnienie blokady.'
      WHEN p_event_type = 'lease_state' AND d->>'to_state' = 'primary' THEN 'Urządzenie zostało aktywowane jako główne.'
      WHEN p_event_type = 'lease_state' AND d->>'to_state' = 'released' THEN 'Urządzenie zwolniło blokadę.'
      WHEN p_event_type = 'lease_state' AND d->>'to_state' = 'expired' THEN 'Blokada urządzenia wygasła.'
      WHEN p_event_type = 'lease_state' AND d->>'to_state' = 'revoked' THEN 'Połączenie urządzenia zostało cofnięte.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'recovered' THEN 'Zakończyła się przerwa w kanale urządzenia; stan pobrany z bazy.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'auth_error' THEN 'Nie udało się pobrać tokenu kanału urządzenia.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'token_refresh' THEN 'Planowa wymiana tokenu kanału urządzenia.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'connected' THEN 'Kanał urządzenia połączony.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'socket_closed' THEN 'Zamknięte połączenie Realtime urządzenia.'
      WHEN p_event_type = 'transport_state' AND d->>'phase' = 'reconnect_scheduled' THEN 'Ponowne dołączanie urządzenia do kanału.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'resync_applied' THEN 'Urządzenie nadrobiło zmiany z przerwy odczytem z bazy.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'render_slow' THEN 'Urządzenie wolno zastosowało nowy stan.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'fallback_catchup' THEN 'Odczyt awaryjny nadrobił zmianę stanu gry (dawny mechanizm).'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'read_error' THEN 'Odczyt stanu gry z bazy nie powiódł się.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'read_recovered' THEN 'Odczyt stanu gry z bazy wrócił.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'render_error' THEN 'Urządzenie odebrało stan gry, ale jego obsługa renderu zgłosiła błąd.'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'render_recovered' THEN 'Renderowanie stanu gry wróciło do działania.'
      WHEN p_event_type = 'transport_state' THEN 'Zmienił się stan kanału urządzenia.'
      WHEN p_event_type = 'state_sync' THEN 'Urządzenie zsynchronizowało stan gry.'
      ELSE 'Zdarzenie urządzenia.' END,
    'metrics', d || jsonb_build_object('reason', p_event_type, 'impact', CASE
      WHEN p_event_type = 'transport_state' AND coalesce((d->>'catchup_count')::integer, 0) > 0 THEN 'fallback_catchup'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'resync_applied' THEN 'resync'
      WHEN p_event_type = 'transport_state' THEN 'transport_recovered'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'render_error' THEN 'render_failure'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'render_recovered' THEN 'render_recovered'
      WHEN p_event_type = 'state_sync' AND d->>'phase' = 'read_error' THEN 'database_read_failure'
      WHEN p_event_type = 'network_state' AND d->>'source' = 'probe' AND d->>'phase' = 'slow' THEN d->>'verdict'
      ELSE NULL END)
  )
$$;


--
-- Name: _control2_diag_bump("uuid", "text", "text", timestamp with time zone, "jsonb", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_diag_bump"("p_game_session_id" "uuid", "p_source" "text", "p_key" "text", "p_at" timestamp with time zone, "d" "jsonb", "p_dropped" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_summary jsonb;
  v_cur jsonb;
  v_dur numeric := coalesce(public._control2_jnum(d, 'duration_ms'), public._control2_jnum(d, 'blocked_duration_ms'),
    public._control2_jnum(d, 'wait_ms'), public._control2_jnum(d, 'actual_ms'), 0);
  v_hidden numeric := coalesce(public._control2_jnum(d, 'hidden_duration_ms'), 0);
  v_max numeric := greatest(coalesce(public._control2_jnum(d, 'max_db_ms'), 0), coalesce(public._control2_jnum(d, 'db_ms'), 0),
    coalesce(public._control2_jnum(d, 'max_edge_ms'), 0), coalesce(public._control2_jnum(d, 'max_frame_gap_ms'), 0),
    coalesce(public._control2_jnum(d, 'fetch_ms'), 0), coalesce(public._control2_jnum(d, 'latency_ms'), 0));
BEGIN
  INSERT INTO public.control2_session_diag(game_session_id) VALUES (p_game_session_id)
    ON CONFLICT (game_session_id) DO NOTHING;
  SELECT summary INTO v_summary FROM public.control2_session_diag
    WHERE game_session_id = p_game_session_id FOR UPDATE;
  v_cur := v_summary #> ARRAY[p_source, p_key];
  IF NOT v_summary ? p_source THEN v_summary := v_summary || jsonb_build_object(p_source, '{}'::jsonb); END IF;
  v_summary := jsonb_set(v_summary, ARRAY[p_source, p_key], jsonb_build_object(
    'n', coalesce((v_cur->>'n')::integer, 0) + 1,
    'first', CASE WHEN v_cur->>'first' IS NULL OR p_at < (v_cur->>'first')::timestamptz THEN p_at ELSE (v_cur->>'first')::timestamptz END,
    'last', CASE WHEN v_cur->>'last' IS NULL OR p_at > (v_cur->>'last')::timestamptz THEN p_at ELSE (v_cur->>'last')::timestamptz END,
    'dur_ms', coalesce((v_cur->>'dur_ms')::bigint, 0) + least(86400000, greatest(0, v_dur))::bigint,
    'hidden_ms', coalesce((v_cur->>'hidden_ms')::bigint, 0) + least(86400000, greatest(0, v_hidden))::bigint,
    'max_ms', greatest(coalesce((v_cur->>'max_ms')::integer, 0), least(3600000, greatest(0, v_max))::integer)
  ));
  UPDATE public.control2_session_diag SET summary = v_summary,
    event_count = event_count + CASE WHEN p_dropped THEN 0 ELSE 1 END,
    dropped_count = dropped_count + CASE WHEN p_dropped THEN 1 ELSE 0 END,
    updated_at = now()
  WHERE game_session_id = p_game_session_id;
END;
$$;


--
-- Name: _control2_diag_key("text", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_diag_key"("p_kind" "text", "p_category" "text", "p_event_type" "text", "d" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN p_kind <> 'diagnostic' THEN p_kind ELSE
    coalesce(p_category, 'other') || coalesce(':' || CASE p_category
      WHEN 'device_lease' THEN d->>'to_state'
      WHEN 'device_network' THEN d->>'phase' || CASE WHEN d->>'phase' = 'slow' THEN ':' || coalesce(d->>'verdict', '?') ELSE '' END
      WHEN 'display_state' THEN coalesce(p_event_type, d->>'reason')
        || CASE WHEN coalesce(p_event_type, d->>'reason') = 'page_state' THEN ':' || coalesce(d->>'visibility', 'unknown') ELSE '' END
      WHEN 'realtime' THEN coalesce(d->>'channel', '?') || ':' || coalesce(d->>'state', '?')
      WHEN 'audio_unlock' THEN coalesce(d->>'outcome', d->>'reason')
      WHEN 'audio_start' THEN CASE WHEN d->>'failed' = 'true' THEN 'failed' ELSE 'started' END
      WHEN 'connectivity' THEN coalesce(d->>'phase', 'outage')
      WHEN 'display_delay' THEN coalesce(d->>'reason', 'delay')
      ELSE coalesce(d->>'phase', d->>'reason', p_event_type) END, '')
  END
$$;


--
-- Name: _control2_game_session_diag_start(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_game_session_diag_start"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE e record;
BEGIN
  IF NEW.control_version <> 2 THEN RETURN NEW; END IF;
  BEGIN
    INSERT INTO public.control2_session_diag(game_session_id, runtime_session_id, game_id, started_at)
      VALUES (NEW.id, NEW.runtime_session_id, NEW.game_id, NEW.started_at)
      ON CONFLICT (game_session_id) DO UPDATE SET runtime_session_id = EXCLUDED.runtime_session_id,
        game_id = EXCLUDED.game_id, started_at = EXCLUDED.started_at;
    IF NEW.runtime_session_id IS NOT NULL THEN
      -- Ta sama blokada co przy zapisie zdarzenia bez sesji: zdarzenie zapisane
      -- równolegle albo zostanie tu dopięte, albo samo znajdzie tę sesję.
      PERFORM pg_advisory_xact_lock(hashtextextended('control2-diag:' || NEW.runtime_session_id::text, 0));
      FOR e IN UPDATE public.control2_session_events SET game_session_id = NEW.id
        WHERE runtime_session_id = NEW.runtime_session_id AND game_session_id IS NULL
        RETURNING source, kind, category, event_type, details, created_at
      LOOP
        PERFORM public._control2_diag_bump(NEW.id, e.source,
          public._control2_diag_key(e.kind, e.category, e.event_type, e.details), e.created_at, e.details, false);
      END LOOP;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Diagnostyka nie może cofnąć startu gry ani statystyk.
    RAISE WARNING 'Control 2 session diagnostics start failed: %', SQLERRM;
  END;
  RETURN NEW;
END;
$$;


--
-- Name: _control2_game_session_link_runtime(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_game_session_link_runtime"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.control_version = 2 AND NEW.runtime_session_id IS NULL THEN
    SELECT r.id INTO NEW.runtime_session_id FROM public.control_runtime_sessions r
    WHERE r.game_id = NEW.game_id AND r.ended_at IS NULL AND r.expires_at > now()
    ORDER BY r.last_activity_at DESC LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: _control2_jnum("jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_jnum"("p" "jsonb", "k" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN jsonb_typeof(p->k) = 'number' THEN (p->>k)::numeric END
$$;


--
-- Name: _control2_log_device_lease_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_log_device_lease_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_from text;
  v_epoch bigint;
  v_event_id text;
  v_game_rev bigint;
  v_details jsonb;
  v_view jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'waiting' OR NOT EXISTS (
      SELECT 1 FROM public.control_device_slots s
      WHERE s.session_id = NEW.session_id AND s.device_type = NEW.device_type
        AND s.primary_connection_id IS NOT NULL AND s.primary_connection_id <> NEW.id
    ) THEN RETURN NEW; END IF;
    v_from := NULL;
    v_epoch := 0;
    v_event_id := 'lease:' || NEW.id::text || ':waiting';
  ELSE
    IF OLD.state IS NOT DISTINCT FROM NEW.state THEN RETURN NEW; END IF;
    v_from := OLD.state;
    v_epoch := coalesce(NEW.epoch, OLD.epoch, 0);
    v_event_id := 'lease:' || NEW.id::text || ':' || NEW.state || ':' || v_epoch::text;
  END IF;

  BEGIN
    SELECT rev INTO v_game_rev FROM public.game_state WHERE game_id = NEW.game_id;
    v_details := jsonb_strip_nulls(jsonb_build_object(
      'device_type', NEW.device_type,
      'from_state', v_from,
      'to_state', NEW.state,
      'epoch', v_epoch,
      'connection_id', NEW.id,
      'visibility', NEW.page_visibility,
      'focused', NEW.focused,
      'received_revision', NEW.received_rev,
      'rendered_revision', NEW.rendered_rev,
      'started_sound_cue_seq', NEW.started_sound_cue_seq,
      'game_revision', v_game_rev,
      'last_seen_age_ms', least(3600000, greatest(0,
        extract(epoch FROM clock_timestamp() - NEW.last_seen_at) * 1000))::integer
    ));
    v_view := public._control2_device_event_view(NEW.device_type, 'lease_state', v_details);
    PERFORM public._control2_session_event_add(
      public._control2_active_game_session(NEW.game_id), NEW.session_id, NEW.game_id, NEW.device_type, NEW.id,
      'diagnostic', v_view->>'category', 'lease_state', v_view->>'message',
      jsonb_build_array(NEW.device_type), v_view->'metrics', v_event_id, now());
  EXCEPTION WHEN OTHERS THEN
    -- Diagnostyka nie może przerwać rejestracji ani odnowienia lease.
    RAISE WARNING 'Control 2 lease event was not recorded: %', SQLERRM;
  END;
  RETURN NEW;
END;
$$;


--
-- Name: _control2_log_typed("uuid", "uuid", "uuid", "text", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_log_typed"("p_game_session_id" "uuid", "p_runtime_session_id" "uuid", "p_game_id" "uuid", "p_source" "text", "p_connection_id" "uuid", "p_event" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_type text := p_event->>'event_type';
  v_details jsonb;
  v_view jsonb;
  v_category text;
  v_message text;
BEGIN
  IF v_type IS NULL OR v_type NOT IN ('page_state','transport_state','state_sync','network_state',
      'render_stall','runtime_error','page_lifecycle','wake_lock','device_info','prize_render','log_delivery') THEN
    RETURN false;
  END IF;
  v_details := public._control2_sanitize_event(p_event) || jsonb_build_object('device_type', p_source);
  IF v_type = 'page_state' THEN
    v_details := (v_details - 'reason') || jsonb_build_object('visibility_reason', p_event->>'reason');
  END IF;
  v_view := public._control2_device_event_view(p_source, v_type, v_details);
  IF v_type = 'runtime_error' THEN
    v_category := 'runtime_error';
    v_message := CASE p_event->>'phase'
      WHEN 'uncaught_error' THEN 'Strona zgłosiła nieobsłużony błąd JavaScript.'
      WHEN 'unhandled_rejection' THEN 'Strona zgłosiła nieobsłużony błąd operacji asynchronicznej.'
      WHEN 'render' THEN 'Strona nie zdołała narysować odebranego stanu.'
      WHEN 'completion_ack' THEN 'Strona nie potwierdziła zakończenia renderowania.'
      ELSE 'Strona zgłosiła błąd działania.' END;
  ELSIF v_type = 'prize_render' THEN
    v_category := 'prize_calculation';
    v_message := 'Wyświetlacz obliczył i pokazał kwotę nagrody.';
  ELSIF v_type = 'log_delivery' THEN
    v_category := 'log_delivery';
    v_message := 'Dziennik diagnostyczny wznowił zapis po przerwie.';
  ELSE
    v_category := v_view->>'category';
    v_message := v_view->>'message';
  END IF;
  RETURN public._control2_session_event_add(p_game_session_id, p_runtime_session_id, p_game_id, p_source,
    p_connection_id, 'diagnostic', v_category, v_type, v_message,
    jsonb_build_array(p_source), v_view->'metrics', p_event->>'event_id', now());
END;
$$;


--
-- Name: _control2_record_prize_calculation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_record_prize_calculation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_settings jsonb := coalesce(NEW.stats_detail->'settings', '{}'::jsonb);
  v_round_points integer;
  v_final_points integer := coalesce(NEW.final_points, 0);
  v_multiplier integer := coalesce((v_settings->>'finalPrizeMultiplier')::integer, 3);
  v_main_prize integer := coalesce((v_settings->>'mainPrizeAmount')::integer, 25000);
  v_hit_target boolean := coalesce((NEW.stats_detail->>'target_reached')::boolean, false);
  v_base integer;
  v_prize integer;
BEGIN
  IF NEW.stats_detail ? 'prize' AND NEW.winner_team IN ('A', 'B') THEN
    v_round_points := CASE NEW.winner_team WHEN 'A' THEN coalesce(NEW.rounds_score_a, 0) ELSE coalesce(NEW.rounds_score_b, 0) END;
    v_base := v_round_points * v_multiplier;
    v_prize := v_base + CASE WHEN v_hit_target THEN v_main_prize ELSE 0 END;
    NEW.stats_detail := NEW.stats_detail || jsonb_build_object(
      'prize_calculation', jsonb_build_object(
        'rule_version', 1,
        'formula', 'winning_round_points * final_prize_multiplier + main_prize_if_target_reached',
        'winner_team', NEW.winner_team,
        'winning_round_points', v_round_points,
        'final_points_excluded_from_multiplier', v_final_points,
        'final_prize_multiplier', v_multiplier,
        'base_prize', v_base,
        'target_reached', v_hit_target,
        'main_prize_amount', v_main_prize,
        'main_prize_awarded', CASE WHEN v_hit_target THEN v_main_prize ELSE 0 END,
        'calculated_prize', v_prize,
        'stored_prize_before_trigger', (NEW.stats_detail->>'prize')::numeric,
        'matches_stored_prize', (NEW.stats_detail->>'prize')::numeric = v_prize
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: _control2_sanitize_event("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_sanitize_event"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  SELECT coalesce(jsonb_object_agg(key, CASE jsonb_typeof(value)
      WHEN 'number' THEN to_jsonb(trim_scale(least(9000000000000000::numeric, greatest(-9000000000000000::numeric, round((value #>> '{}')::numeric, 3)))))
      ELSE value END), '{}'::jsonb)
  FROM (
    SELECT key, value FROM jsonb_each(CASE WHEN jsonb_typeof(p) = 'object' THEN p ELSE '{}'::jsonb END)
    WHERE key ~ '^[a-z][a-z0-9_]{0,39}$' AND key NOT IN ('event_id', 'event_type')
      AND (jsonb_typeof(value) IN ('number', 'boolean')
        OR (jsonb_typeof(value) = 'string' AND (value #>> '{}') ~ '^[A-Za-z0-9_.:/+-]{0,80}$'))
    ORDER BY key LIMIT 40
  ) x
$_$;


--
-- Name: _control2_session_close("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_session_close"("p_session_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Rozegrany finał (f_end): gra skończona, brakowało tylko „Zakończ”
  -- (FINISH_FINAL dolicza finał zwycięzcy). ended_at = ostatnia zmiana gry.
  UPDATE public.game_sessions
  SET status='final',
      ended_at=coalesce(last_seen_at, clock_timestamp()),
      team_a_score=team_a_score + CASE WHEN winner_team='A' THEN final_points ELSE 0 END,
      team_b_score=team_b_score + CASE WHEN winner_team='B' THEN final_points ELSE 0 END,
      stats_detail=coalesce(stats_detail,'{}'::jsonb) || jsonb_build_object('closed_by',p_reason)
  WHERE id=p_session_id AND ended_at IS NULL
    AND stats_detail->>'last_step'='f_end' AND final_points IS NOT NULL;
  IF FOUND THEN RETURN; END IF;

  UPDATE public.game_sessions
  SET status='abandoned', ended_at=clock_timestamp(), last_seen_at=clock_timestamp(),
      stats_detail=coalesce(stats_detail,'{}'::jsonb) || jsonb_build_object('end_reason',p_reason)
  WHERE id=p_session_id AND ended_at IS NULL;
END;
$$;


--
-- Name: _control2_session_event_add("uuid", "uuid", "uuid", "text", "uuid", "text", "text", "text", "text", "jsonb", "jsonb", "text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control2_session_event_add"("p_game_session_id" "uuid", "p_runtime_session_id" "uuid", "p_game_id" "uuid", "p_source" "text", "p_connection_id" "uuid", "p_kind" "text", "p_category" "text", "p_event_type" "text", "p_message" "text", "p_devices" "jsonb", "p_details" "jsonb", "p_event_id" "text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
  v_id bigint;
  v_game_session uuid := p_game_session_id;
  v_details jsonb := coalesce(p_details, '{}'::jsonb);
  v_key text := public._control2_diag_key(p_kind, p_category, p_event_type, coalesce(p_details, '{}'::jsonb));
BEGIN
  IF v_game_session IS NULL AND p_runtime_session_id IS NULL THEN RETURN false; END IF;
  IF v_game_session IS NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('control2-diag:' || p_runtime_session_id::text, 0));
    SELECT s.id INTO v_game_session FROM public.game_sessions s
    WHERE s.runtime_session_id = p_runtime_session_id AND s.control_version = 2 AND s.ended_at IS NULL
    ORDER BY s.started_at DESC LIMIT 1;
  END IF;
  IF v_game_session IS NOT NULL THEN
    SELECT event_count INTO v_count FROM public.control2_session_diag WHERE game_session_id = v_game_session;
  ELSE
    SELECT count(*) INTO v_count FROM (
      SELECT 1 FROM public.control2_session_events
      WHERE runtime_session_id = p_runtime_session_id AND game_session_id IS NULL LIMIT 3000
    ) x;
  END IF;
  IF coalesce(v_count, 0) >= 3000 THEN
    IF v_game_session IS NOT NULL THEN
      PERFORM public._control2_diag_bump(v_game_session, p_source, v_key, p_at, v_details, true);
    END IF;
    RETURN false;
  END IF;
  INSERT INTO public.control2_session_events(
    game_session_id, runtime_session_id, game_id, source, connection_id, kind, category,
    event_type, message, devices, details, event_id, created_at
  ) VALUES (
    v_game_session, p_runtime_session_id, p_game_id, p_source, p_connection_id, p_kind, p_category,
    p_event_type, left(p_message, 1000),
    CASE WHEN jsonb_typeof(p_devices) = 'array' THEN p_devices ELSE '[]'::jsonb END,
    v_details, nullif(left(p_event_id, 80), ''), p_at
  ) ON CONFLICT (game_id, event_id) WHERE event_id IS NOT NULL DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN false; END IF;
  IF v_game_session IS NOT NULL THEN
    PERFORM public._control2_diag_bump(v_game_session, p_source, v_key, p_at, v_details, false);
  END IF;
  RETURN true;
END;
$$;


--
-- Name: _control_broadcast("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_broadcast"("p_game_id" "uuid", "p_event" "text", "p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target record;
BEGIN
  IF to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NULL THEN RETURN; END IF;
  FOR v_target IN
    SELECT slot.primary_connection_id AS connection_id
    FROM public.control_runtime_sessions s
    JOIN public.control_device_slots slot ON slot.session_id = s.id
    WHERE s.game_id = p_game_id AND s.device_protocol = 2
      AND s.ended_at IS NULL AND s.expires_at > clock_timestamp()
      AND slot.game_id = p_game_id
      AND slot.primary_connection_id IS NOT NULL
      AND slot.lease_expires_at > clock_timestamp()
  LOOP
    BEGIN
      PERFORM realtime.send(p_payload, p_event, format('game-state:%s:%s', p_game_id, v_target.connection_id), true);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'control broadcast (device) failed: %', SQLSTATE;
    END;
  END LOOP;
  BEGIN
    PERFORM realtime.send(p_payload, p_event, format('game-control:%s', p_game_id), true);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'control broadcast (control) failed: %', SQLSTATE;
  END;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'control broadcast skipped: %', SQLSTATE;
END;
$$;


--
-- Name: _control_device_action_valid("uuid", "text", "text", "uuid", bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_device_action_valid"("p_game_id" "uuid", "p_device_type" "text", "p_key" "text", "p_connection_id" "uuid", "p_epoch" bigint) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_session_id uuid;
BEGIN
  IF NOT public.control_device_key_valid(p_game_id,p_device_type,p_key) THEN RETURN false; END IF;
  v_session_id := public._control_device_session_for_key(p_game_id,p_device_type,p_key);
  IF NOT EXISTS (SELECT 1 FROM public.control_runtime_sessions
    WHERE id=v_session_id AND game_id=p_game_id AND device_protocol=2
      AND ended_at IS NULL AND expires_at>now()) THEN RETURN false; END IF;
  IF p_connection_id IS NULL OR p_epoch IS NULL THEN RETURN false; END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.control_device_connections c
    JOIN public.control_device_slots s ON s.session_id=c.session_id AND s.device_type=c.device_type
    WHERE c.id=p_connection_id AND c.session_id=v_session_id AND c.game_id=p_game_id
      AND c.device_type=p_device_type AND c.state='primary' AND c.epoch=p_epoch
      AND c.last_seen_at>clock_timestamp()-interval '12 seconds'
      AND s.primary_connection_id=c.id AND s.epoch=p_epoch
      AND s.lease_expires_at>clock_timestamp()
  );
END;
$$;


--
-- Name: _control_device_promote_waiting("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_device_promote_waiting"("p_session_id" "uuid", "p_device_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slot public.control_device_slots;
  v_candidate uuid;
  v_epoch bigint;
BEGIN
  SELECT * INTO v_slot FROM public.control_device_slots
  WHERE session_id=p_session_id AND device_type=p_device_type FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF v_slot.primary_connection_id IS NOT NULL
     AND v_slot.lease_expires_at > clock_timestamp()
     AND EXISTS (
       SELECT 1 FROM public.control_device_connections c
       WHERE c.id=v_slot.primary_connection_id AND c.state='primary'
         AND c.last_seen_at > clock_timestamp()-interval '12 seconds'
     ) THEN
    RETURN v_slot.primary_connection_id;
  END IF;

  IF v_slot.primary_connection_id IS NOT NULL THEN
    UPDATE public.control_device_connections SET state='expired',epoch=NULL
    WHERE id=v_slot.primary_connection_id AND state='primary';
  END IF;
  UPDATE public.control_device_connections SET state='expired',epoch=NULL
  WHERE session_id=p_session_id AND device_type=p_device_type AND state='waiting'
    AND last_seen_at<=clock_timestamp()-interval '12 seconds';

  SELECT c.id INTO v_candidate
  FROM public.control_device_connections c
  WHERE c.session_id=p_session_id AND c.device_type=p_device_type
    AND c.state='waiting' AND c.last_seen_at > clock_timestamp()-interval '12 seconds'
  ORDER BY c.requested_at,c.id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF v_candidate IS NULL THEN
    UPDATE public.control_device_slots SET primary_connection_id=NULL,
      epoch=CASE WHEN v_slot.primary_connection_id IS NULL THEN v_slot.epoch ELSE v_slot.epoch+1 END,
      lease_expires_at=NULL,updated_at=clock_timestamp()
    WHERE session_id=p_session_id AND device_type=p_device_type;
    RETURN NULL;
  END IF;

  v_epoch := v_slot.epoch + 1;
  UPDATE public.control_device_connections SET state='primary',epoch=v_epoch
  WHERE id=v_candidate;
  UPDATE public.control_device_slots SET primary_connection_id=v_candidate,epoch=v_epoch,
    lease_expires_at=clock_timestamp()+interval '12 seconds',updated_at=clock_timestamp()
  WHERE session_id=p_session_id AND device_type=p_device_type;
  RETURN v_candidate;
END;
$$;


--
-- Name: _control_device_replace_if_other_primary("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_device_replace_if_other_primary"("p_connection_id" "uuid", "p_primary" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.control_device_connections
  SET state='replaced',epoch=NULL,released_at=clock_timestamp()
  WHERE id=p_connection_id AND state='waiting'
    AND p_primary IS NOT NULL AND p_primary<>p_connection_id;
$$;


--
-- Name: _control_device_session_for_key("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_device_session_for_key"("p_game_id" "uuid", "p_device_type" "text", "p_key" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT t.session_id
  FROM public.control_device_link_tokens t
  JOIN public.control_runtime_sessions s ON s.id=t.session_id
  WHERE t.game_id=p_game_id AND t.device_type=p_device_type AND t.token::text=p_key
    AND s.ended_at IS NULL AND s.expires_at>now()
  UNION ALL
  SELECT sh.session_id
  FROM public.control_device_shares sh
  JOIN public.control_runtime_sessions s ON s.id=sh.session_id
  WHERE sh.game_id=p_game_id AND sh.device_type=p_device_type AND sh.token::text=p_key
    AND sh.revoked_at IS NULL AND s.ended_at IS NULL AND s.expires_at>now()
  LIMIT 1
$$;


--
-- Name: _control_device_status("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_device_status"("p_session_id" "uuid", "p_device_type" "text", "p_connection_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_connection public.control_device_connections;
  v_slot public.control_device_slots;
  v_position integer;
  v_waiting integer;
BEGIN
  SELECT * INTO v_connection FROM public.control_device_connections
  WHERE id=p_connection_id AND session_id=p_session_id AND device_type=p_device_type;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'state','missing'); END IF;
  SELECT * INTO v_slot FROM public.control_device_slots
  WHERE session_id=p_session_id AND device_type=p_device_type;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'state',v_connection.state); END IF;
  SELECT count(*)::integer INTO v_waiting FROM public.control_device_connections
  WHERE session_id=p_session_id AND device_type=p_device_type AND state='waiting'
    AND last_seen_at>clock_timestamp()-interval '12 seconds';
  IF v_connection.state='waiting' THEN
    SELECT count(*)::integer+1 INTO v_position FROM public.control_device_connections c
    WHERE c.session_id=p_session_id AND c.device_type=p_device_type AND c.state='waiting'
      AND c.last_seen_at>clock_timestamp()-interval '12 seconds'
      AND (c.requested_at,c.id)<(v_connection.requested_at,v_connection.id);
  END IF;
  RETURN jsonb_build_object('ok',true,'state',v_connection.state,
    'epoch',v_connection.epoch,'lease_expires_at',v_slot.lease_expires_at,
    'waiting_count',v_waiting,'queue_position',v_position);
END;
$$;


--
-- Name: _control_share_recipient_lookup("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_control_share_recipient_lookup"("p_game_id" "uuid", "p_lookup" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE uid uuid:=auth.uid(); raw text:=lower(trim(p_lookup)); peer uuid; mail text;
BEGIN
 IF uid IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=uid AND public._poll_identity_regular(u.id,to_jsonb(u)))
 OR NOT EXISTS(SELECT 1 FROM public.games WHERE id=p_game_id AND owner_id=uid)
 THEN RETURN jsonb_build_object('ok',false,'error','forbidden'); END IF;
 IF position('@' in raw)>0 THEN
  IF raw !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN RETURN jsonb_build_object('ok',false,'error','invalid_email'); END IF;
  peer:=public._poll_registered_uid(raw); mail:=raw;
 ELSE
  SELECT u.id,public._norm_email(u.email) INTO peer,mail FROM public.profiles p JOIN auth.users u ON u.id=p.id
   WHERE lower(trim(p.username))=raw AND public._poll_identity_regular(u.id,to_jsonb(u));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','unknown_user'); END IF;
 END IF;
 RETURN jsonb_build_object('ok',true,'recipient_id',peer,'email',mail,'by_email',position('@' in raw)>0);
END $_$;


--
-- Name: _copy_decide("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_copy_decide"("p_offer" "uuid", "p_decision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); item public.resource_copy_offers; target uuid;
BEGIN
 IF actor IS NULL THEN RETURN jsonb_build_object('ok',false,'error','auth_required'); END IF;
 IF p_decision NOT IN('accept','decline') THEN RETURN jsonb_build_object('ok',false,'error','invalid_decision'); END IF;
 PERFORM 1 FROM auth.users WHERE id=actor FOR NO KEY UPDATE NOWAIT;
 SELECT * INTO item FROM public.resource_copy_offers WHERE id=p_offer AND recipient_id=actor FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not_found'); END IF;
 IF item.status IN('declined','expired') THEN RETURN jsonb_build_object('ok',false,'error',item.status); END IF;
 IF item.status='accepted' AND p_decision='decline' THEN RETURN jsonb_build_object('ok',false,'error','already_accepted'); END IF;
 IF item.status='pending' AND item.created_at+interval '5 days'<=clock_timestamp() THEN
  PERFORM public._copy_discard(item.id,'expired'); RETURN jsonb_build_object('ok',false,'error','expired');
 END IF;
 IF p_decision='decline' THEN PERFORM public._copy_discard(item.id,'declined'); RETURN jsonb_build_object('ok',true); END IF;
 target:=CASE item.resource_kind WHEN 'game' THEN item.game_id ELSE item.logo_id END;
 IF target IS NULL THEN RETURN jsonb_build_object('ok',false,'error','previously_removed'); END IF;
 UPDATE public.resource_copy_offers SET status='accepted',decided_at=coalesce(decided_at,clock_timestamp()) WHERE id=item.id;
 RETURN jsonb_build_object('ok',true,'id',target,'already',item.status='accepted');
END $$;


--
-- Name: _copy_discard("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_copy_discard"("p_offer" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE item public.resource_copy_offers;
BEGIN
 IF p_status NOT IN('declined','expired') THEN RAISE EXCEPTION 'invalid_copy_decision'; END IF;
 SELECT * INTO item FROM public.resource_copy_offers WHERE id=p_offer FOR UPDATE;
 IF NOT FOUND OR item.status<>'pending' THEN RETURN; END IF;
 -- The authoritative state changes before deleting children, within one transaction.
 UPDATE public.resource_copy_offers SET status=p_status,decided_at=clock_timestamp(),game_id=NULL,logo_id=NULL WHERE id=p_offer;
 IF item.game_id IS NOT NULL THEN DELETE FROM public.games WHERE id=item.game_id AND owner_id=item.recipient_id; END IF;
 IF item.logo_id IS NOT NULL THEN DELETE FROM public.user_logos WHERE id=item.logo_id AND user_id=item.recipient_id; END IF;
END $$;


--
-- Name: _copy_pending_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_copy_pending_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE ids uuid[]; question_ids uuid[]; old_row jsonb; new_row jsonb; kind text:='game';
BEGIN
 IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME IN('games','user_logos') THEN
  ids:=ARRAY[(old_row->>'id')::uuid,(new_row->>'id')::uuid];
  IF TG_TABLE_NAME='user_logos' THEN kind:='logo'; END IF;
 ELSIF TG_TABLE_NAME='market_games' THEN
  ids:=ARRAY[(old_row->>'source_game_id')::uuid,(new_row->>'source_game_id')::uuid];
 ELSIF TG_TABLE_NAME='answers' THEN
  question_ids:=ARRAY[(old_row->>'question_id')::uuid,(new_row->>'question_id')::uuid];
  SELECT array_agg(game_id) INTO ids FROM public.questions WHERE id=ANY(question_ids);
 ELSE ids:=ARRAY[(old_row->>'game_id')::uuid,(new_row->>'game_id')::uuid]; END IF;
 IF EXISTS(SELECT 1 FROM public.resource_copy_offers o JOIN auth.users u ON u.id=o.recipient_id
  WHERE o.status='pending' AND u.deleted_at IS NULL AND o.resource_kind=kind
   AND CASE kind WHEN 'game' THEN o.game_id ELSE o.logo_id END=ANY(ids)) THEN
  RAISE EXCEPTION 'received_copy_pending';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: _delete_user_data("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_delete_user_data"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_emails text[];
  v_email text;
  fk record;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required';
  end if;

  -- 312: e-maile konta (małymi literami) -- po nich czyścimy dane bez user_id
  select coalesce(array_agg(distinct e), array[]::text[]) into v_emails
  from (
    select lower(trim(u.email)) as e from auth.users u where u.id = p_user_id
    union
    select lower(trim(p.email)) from public.profiles p where p.id = p_user_id
  ) x
  where e is not null and e <> '';

  -- Serialize against snapshot/write jobs before inspecting the inbox.
  perform 1 from auth.users where id = p_user_id for update;

  --366: remove only this recipient inbox before pending resource guards.
  -- Sent copies already belong to their recipients and remain independent.
  delete from public.resource_copy_offers where recipient_id = p_user_id;

  -- 312: usunięcie konta jest nadrzędne -- nie sprawdza blokad (edit_locks);
  -- blokady trzymane przez to konto i na jego zasobach znikają.
  delete from public.edit_locks where holder_user_id = p_user_id;
  delete from public.edit_locks
   where (resource_type = 'game' and resource_id in (select id from public.games where owner_id = p_user_id))
      or (resource_type = 'base' and resource_id in (select id from public.question_bases where owner_id = p_user_id))
      or (resource_type = 'logo' and resource_id in (select id from public.user_logos where user_id = p_user_id));

  -- 312: głosy w cudzych ankietach zostają anonimowe (bez powiązania z kontem);
  -- głosy w własnych grach znikają razem z grami niżej.
  update public.poll_text_entries set voter_user_id = null where voter_user_id = p_user_id;
  update public.poll_votes set voter_user_id = null where voter_user_id = p_user_id;

  delete from public.friendships where requester_id=p_user_id OR addressee_id=p_user_id;

  delete from public.poll_subscriptions where registered_user_id = p_user_id;
  delete from public.poll_subscriptions where owner_id = p_user_id;

  delete from public.poll_tasks where recipient_user_id = p_user_id;
  delete from public.poll_tasks where owner_id = p_user_id;

  -- 312: zaproszenia do baz (po user_id i po e-mailu)
  delete from public.base_share_tasks where recipient_user_id = p_user_id;
  delete from public.base_share_tasks where owner_id = p_user_id;

  delete from public.question_base_shares where user_id = p_user_id;
  delete from public.question_bases where owner_id = p_user_id;

  -- 312: gry (maile ankietowe właściciela znikają niżej przez created_by)
  delete from public.games where owner_id = p_user_id;

  delete from public.user_flags where user_id = p_user_id;
  delete from public.user_logos where user_id = p_user_id;

  -- 312: wszystko powiązane z e-mailem konta
  delete from public.mail_queue where created_by = p_user_id;
  delete from public.mail_function_logs where actor_user_id = p_user_id;
  delete from public.email_intents where user_id = p_user_id;
  delete from public.mail_cooldowns
   where position(p_user_id::text in target_key) > 0;

  foreach v_email in array v_emails loop
    delete from public.poll_subscriptions where lower(subscriber_email) = v_email;
    delete from public.poll_tasks where lower(recipient_email) = v_email;
    delete from public.base_share_tasks where lower(recipient_email) = v_email;
    delete from public.mail_queue where lower(trim(to_email)) = v_email;
    delete from public.mail_function_logs where lower(recipient_email) = v_email;
    delete from public.email_unsub_tokens where lower(email) = v_email;
    delete from public.email_intents where lower(email) = v_email;
    delete from public.email_cooldowns where email_hash = md5(v_email);
    delete from public.mail_cooldowns where position(md5(v_email) in target_key) > 0;
    -- zgłoszenia kontaktowe zostają (decyzja 2026-10-23), tylko oznaczone:
    -- autor = pierwsza wiadomość zgłoszenia (jak w Workerze, email/contact.js)
    update public.reports r set author_account_deleted_at = coalesce(r.author_account_deleted_at, now())
    where lower(trim((
      select case when m.direction = 'inbound' then m.from_email else m.to_email end
      from public.messages m where m.report_id = r.id order by m.created_at, m.id limit 1
    ))) = v_email;
  end loop;


  -- 460: ogólny przebieg po kluczach obcych do kont -- to, co przy usuwaniu
  -- konta zrobiłaby kaskada (ON DELETE CASCADE / SET NULL), tutaj jawnie,
  -- żeby czyszczenie bez usuwania profilu (e2e_reset_identity) było pełne.
  -- Nowa tabela z kluczem do profiles/auth.users jest objęta automatycznie.
  for fk in
    select c.conrelid::regclass as tbl, a.attname as col, c.confdeltype as act
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f' and array_length(c.conkey, 1) = 1
      and c.confrelid in ('public.profiles'::regclass, 'auth.users'::regclass)
      and c.conrelid not in ('public.profiles'::regclass,
                             'public.reserved_username_accounts'::regclass,
                             'public.stats_excluded_users'::regclass,
                             'public.e2e_identities'::regclass)
      and c.confdeltype in ('c', 'n')
    order by c.conrelid::regclass::text, a.attname
  loop
    if fk.act = 'c' then
      execute format('delete from %s where %I = $1', fk.tbl, fk.col) using p_user_id;
    else
      execute format('update %s set %I = null where %I = $1', fk.tbl, fk.col, fk.col) using p_user_id;
    end if;
  end loop;
end;
$_$;


--
-- Name: _demo_apply_pending("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_apply_pending"("p_type" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
 IF p_type NOT IN ('game','logo','logos','base') THEN RETURN; END IF;
 FOR r IN SELECT t.update_id, t.resource_id FROM admin_demo_targets t
   WHERE t.status='queued' AND (
    (p_type IN ('game','logo','base') AND t.kind=p_type AND t.resource_id=p_id) OR
    (p_type='logos' AND t.kind='logo' AND t.resource_id IN (SELECT id FROM user_logos WHERE user_id=p_id AND is_demo)))
   ORDER BY t.update_id LOOP
  PERFORM public._demo_apply_target(r.update_id, r.resource_id);
 END LOOP;
END $$;


--
-- Name: _demo_apply_target("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_apply_target"("p_update" "uuid", "p_resource" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE t admin_demo_targets; job admin_demo_updates; cur jsonb; owner uuid; key text;
BEGIN
 SELECT * INTO t FROM admin_demo_targets WHERE update_id=p_update AND resource_id=p_resource AND status='queued' FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO job FROM admin_demo_updates WHERE id=t.update_id;
 key := public._demo_lock_key(t.kind, t.resource_id);
 IF key IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(key,0)); END IF;
 BEGIN
  IF t.kind='game' THEN SELECT owner_id INTO owner FROM games WHERE id=t.resource_id FOR UPDATE NOWAIT;
  ELSIF t.kind='base' THEN SELECT owner_id INTO owner FROM question_bases WHERE id=t.resource_id FOR UPDATE NOWAIT;
  ELSE SELECT user_id INTO owner FROM user_logos WHERE id=t.resource_id FOR UPDATE NOWAIT; END IF;
  cur := public._demo_current_definition(t.kind, t.resource_id);
  IF cur IS NULL THEN
   UPDATE admin_demo_targets SET status='removed',message='' WHERE update_id=t.update_id AND resource_id=t.resource_id; RETURN 'removed';
  END IF;
  IF cur IS DISTINCT FROM coalesce(t.expected_definition, job.old_definition) THEN
   UPDATE admin_demo_targets SET status='edited',message='' WHERE update_id=t.update_id AND resource_id=t.resource_id; RETURN 'edited';
  END IF;
  IF public._demo_in_use(t.kind, t.resource_id) THEN RAISE lock_not_available; END IF;
  PERFORM public._demo_write(t.kind, t.resource_id, job.slot, job.new_payload);
  UPDATE admin_demo_targets SET status='updated',message='' WHERE update_id=t.update_id AND resource_id=t.resource_id;
  RETURN 'updated';
 EXCEPTION WHEN lock_not_available THEN
  UPDATE admin_demo_targets SET message='Czeka: materiał jest używany; zaktualizuje się po zwolnieniu albo przy następnym otwarciu.'
   WHERE update_id=t.update_id AND resource_id=t.resource_id;
  RETURN 'waiting';
 WHEN OTHERS THEN
  UPDATE admin_demo_targets SET status='failed',message=left(SQLSTATE||': '||SQLERRM,200) WHERE update_id=t.update_id AND resource_id=t.resource_id;
  RETURN 'failed';
 END;
END $$;


--
-- Name: _demo_base_canonical("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_base_canonical"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 WITH RECURSIVE cats AS (
  SELECT c,c->>'id' id, jsonb_build_array(jsonb_build_array(coalesce(c->>'ord','0'),c->>'name')) path FROM jsonb_array_elements(coalesce(p->'categories','[]')) c WHERE coalesce(c->>'parent_id','')=''
  UNION ALL SELECT c,c->>'id',parent.path||jsonb_build_array(jsonb_build_array(coalesce(c->>'ord','0'),c->>'name')) FROM jsonb_array_elements(coalesce(p->'categories','[]')) c JOIN cats parent ON c->>'parent_id'=parent.id
 ), tags AS (SELECT t,t->>'id' id,jsonb_build_array(t->>'name',t->>'color',coalesce(t->>'ord','0')) val FROM jsonb_array_elements(coalesce(p->'tags','[]')) t)
 SELECT jsonb_build_object('name',p#>>'{base,name}',
 'categories',coalesce((SELECT jsonb_agg(path ORDER BY path::text) FROM cats),'[]'),
 'tags',coalesce((SELECT jsonb_agg(val ORDER BY val::text) FROM tags),'[]'),
 'questions',coalesce((SELECT jsonb_agg(val ORDER BY val::text) FROM (
  SELECT jsonb_build_object('category',c.path,'ord',coalesce(q->>'ord','0'),'payload',q->'payload','tags',coalesce((SELECT jsonb_agg(t.val ORDER BY t.val::text) FROM jsonb_array_elements(coalesce(p->'question_tags','[]')) e JOIN tags t ON t.id=e->>'tag_id' WHERE e->>'question_id'=q->>'id'),'[]')) val
   FROM jsonb_array_elements(coalesce(p->'questions','[]')) q LEFT JOIN cats c ON c.id=q->>'category_id') s),'[]'),
 'category_tags',coalesce((SELECT jsonb_agg(jsonb_build_array(c.path,t.val) ORDER BY c.path::text,t.val::text) FROM jsonb_array_elements(coalesce(p->'category_tags','[]')) e JOIN cats c ON c.id=e->>'category_id' JOIN tags t ON t.id=e->>'tag_id'),'[]'))
$$;


--
-- Name: _demo_current_definition("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_current_definition"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE result jsonb; packet jsonb;
BEGIN
 IF p_kind='logo' THEN
  SELECT jsonb_build_object('name',name,'type',type,'payload',payload) INTO result FROM user_logos WHERE id=p_id AND is_demo;
 ELSIF p_kind='game' THEN
  SELECT jsonb_build_object('name',g.name,'type',g.type,'status',g.status,'settings',g.settings,
   'questions',coalesce((SELECT jsonb_agg(jsonb_build_object('text',q.text,'answers',coalesce((SELECT jsonb_agg(jsonb_build_object('text',a.text,'fixed_points',a.fixed_points) ORDER BY a.ord,a.id) FROM answers a WHERE a.question_id=q.id),'[]')) ORDER BY q.ord,q.id) FROM questions q WHERE q.game_id=g.id),'[]'),
   'votes',coalesce((SELECT jsonb_agg(jsonb_build_object('q',ord,'text',text,'count',n) ORDER BY ord,text) FROM (
    SELECT ord,text,count(*) n FROM (
     SELECT q.ord,e.answer_raw text FROM poll_text_entries e JOIN questions q ON q.id=e.question_id WHERE e.game_id=g.id
     UNION ALL SELECT q.ord,a.text FROM poll_votes v JOIN questions q ON q.id=v.question_id JOIN answers a ON a.id=v.answer_id WHERE v.game_id=g.id
    ) x GROUP BY ord,text) v),'[]')) INTO result FROM games g WHERE g.id=p_id AND g.is_demo;
 ELSIF p_kind='base' THEN
  SELECT jsonb_build_object('base',jsonb_build_object('name',b.name),
   'categories',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM qb_categories c WHERE base_id=p_id),'[]'),
   'tags',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM qb_tags t WHERE base_id=p_id),'[]'),
   'questions',coalesce((SELECT jsonb_agg(to_jsonb(q)) FROM qb_questions q WHERE base_id=p_id),'[]'),
   'question_tags',coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM qb_question_tags e JOIN qb_questions q ON q.id=e.question_id WHERE q.base_id=p_id),'[]'),
   'category_tags',coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM qb_category_tags e JOIN qb_categories c ON c.id=e.category_id WHERE c.base_id=p_id),'[]')) INTO packet FROM question_bases b WHERE b.id=p_id AND b.is_demo;
  IF packet IS NOT NULL THEN result:=public._demo_base_canonical(packet); END IF;
 END IF;
 RETURN result;
END $$;


--
-- Name: _demo_in_use("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_in_use"("p_kind" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS (SELECT 1 FROM public.edit_lock_blockers(p_kind, p_id, 'exclusive', 'demo-update'))
  OR (p_kind='base' AND EXISTS (SELECT 1 FROM public.edit_locks l
       WHERE l.heartbeat_at > now() - public.edit_lock_ttl() AND (
        (l.resource_type='base_question' AND l.resource_id IN (SELECT id FROM qb_questions WHERE base_id=p_id)) OR
        (l.resource_type='base_folder' AND l.resource_id IN (SELECT id FROM qb_categories WHERE base_id=p_id)) OR
        (l.resource_type='base_tag' AND l.resource_id IN (SELECT id FROM qb_tags WHERE base_id=p_id)))))
$$;


--
-- Name: _demo_lock_key("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_lock_key"("p_kind" "text", "p_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT CASE p_kind WHEN 'logo' THEN 'logos:'||(SELECT user_id FROM user_logos WHERE id=p_id)::text
                    ELSE p_kind||':'||p_id::text END
$$;


--
-- Name: _demo_template_definition("text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_template_definition"("p_slot" "text", "p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE typ text; state text; qs jsonb; vs jsonb;
BEGIN
 IF p_slot='base' THEN RETURN public._demo_base_canonical(p); END IF;
 IF p_slot LIKE 'logo_%' THEN RETURN jsonb_build_object('name',p->>'name','type',CASE WHEN p->>'kind'='GLYPH' THEN 'GLYPH_30x10' ELSE 'PIX_150x70' END,'payload',p->'payload'); END IF;
 typ:=CASE WHEN p_slot='prepared' THEN 'prepared' WHEN p_slot LIKE 'poll_text_%' THEN 'poll_text' ELSE 'poll_points' END;
 state:=CASE WHEN p_slot LIKE '%_open' THEN 'poll_open' WHEN p_slot LIKE '%_closed' THEN 'ready' ELSE 'draft' END;
 SELECT coalesce(jsonb_agg(jsonb_build_object('text',q->>'text','answers',coalesce((SELECT jsonb_agg(jsonb_build_object('text',left(btrim(a->>'text'),17),'fixed_points',coalesce((a->>'fixed_points')::int,0)) ORDER BY ai) FROM jsonb_array_elements(coalesce(q->'answers','[]')) WITH ORDINALITY x(a,ai)),'[]')) ORDER BY qi),'[]') INTO qs FROM jsonb_array_elements(coalesce(p->'questions','[]')) WITH ORDINALITY x(q,qi);
 WITH votes AS (
  SELECT ord::int q,a#>>'{}' text FROM jsonb_array_elements(coalesce(p->'votes','[]')) v CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'answers_raw','[]')) WITH ORDINALITY x(a,ord) WHERE p_slot='poll_text_open'
  UNION ALL
  SELECT ord::int,p->'questions'->(ord::int-1)->'answers'->(a#>>'{}')::int->>'text' FROM jsonb_array_elements(coalesce(p->'votes','[]')) v CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'picks','[]')) WITH ORDINALITY x(a,ord) WHERE p_slot='poll_points_open'
  UNION ALL
  SELECT (v->>'question')::int,CASE WHEN p_slot='poll_text_open' THEN v->>'text' ELSE p->'questions'->((v->>'question')::int-1)->'answers'->((v->>'answer')::int-1)->>'text' END
  FROM jsonb_array_elements(coalesce(p->'demo_vote_counts','[]')) v CROSS JOIN LATERAL generate_series(1,(v->>'count')::int) n
 ), grouped AS(SELECT q,text,count(*) n FROM votes GROUP BY q,text)
 SELECT coalesce(jsonb_agg(jsonb_build_object('q',q,'text',text,'count',n) ORDER BY q,text),'[]') INTO vs FROM grouped;
 RETURN jsonb_build_object('name',p#>>'{game,name}','type',typ,'status',state,'settings','{}'::jsonb,'questions',qs,'votes',vs);
END $$;


--
-- Name: _demo_write("text", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_demo_write"("p_kind" "text", "p_id" "uuid", "p_slot" "text", "p" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE q jsonb; a jsonb; v jsonb; qi integer; ai integer; vi integer; off integer; qid uuid; aid uuid; sid uuid;
 qids uuid[]:='{}'; sids uuid[]:='{}'; amap jsonb:='{}'; cmap jsonb; tmap jsonb; qmap jsonb; owner uuid;
 typ game_type; stat game_status; definition jsonb;
BEGIN
 IF p_kind='logo' THEN
  UPDATE user_logos SET name=p->>'name',type=CASE WHEN p->>'kind'='GLYPH' THEN 'GLYPH_30x10' ELSE 'PIX_150x70' END,payload=p->'payload' WHERE id=p_id;
  RETURN;
 ELSIF p_kind='base' THEN
  SELECT owner_id INTO owner FROM question_bases WHERE id=p_id;
  DELETE FROM qb_categories WHERE base_id=p_id;
  DELETE FROM qb_questions WHERE base_id=p_id;
  DELETE FROM qb_tags WHERE base_id=p_id;
  UPDATE question_bases SET name=p#>>'{base,name}' WHERE id=p_id;
  SELECT coalesce(jsonb_object_agg(x->>'id',gen_random_uuid()),'{}') INTO cmap FROM jsonb_array_elements(p->'categories') x;
  SELECT coalesce(jsonb_object_agg(x->>'id',gen_random_uuid()),'{}') INTO tmap FROM jsonb_array_elements(p->'tags') x;
  SELECT coalesce(jsonb_object_agg(x->>'id',gen_random_uuid()),'{}') INTO qmap FROM jsonb_array_elements(p->'questions') x;
  INSERT INTO qb_categories(id,base_id,parent_id,name,ord) SELECT (cmap->>(x->>'id'))::uuid,p_id,(cmap->>(x->>'parent_id'))::uuid,x->>'name',coalesce((x->>'ord')::int,0) FROM jsonb_array_elements(p->'categories') x;
  INSERT INTO qb_tags(id,base_id,name,color,ord) SELECT (tmap->>(x->>'id'))::uuid,p_id,x->>'name',x->>'color',coalesce((x->>'ord')::int,0) FROM jsonb_array_elements(p->'tags') x;
  INSERT INTO qb_questions(id,base_id,category_id,ord,payload,updated_by) SELECT (qmap->>(x->>'id'))::uuid,p_id,(cmap->>(x->>'category_id'))::uuid,coalesce((x->>'ord')::int,0),x->'payload',owner FROM jsonb_array_elements(p->'questions') x;
  INSERT INTO qb_question_tags(question_id,tag_id) SELECT (qmap->>(x->>'question_id'))::uuid,(tmap->>(x->>'tag_id'))::uuid FROM jsonb_array_elements(p->'question_tags') x;
  INSERT INTO qb_category_tags(category_id,tag_id) SELECT (cmap->>(x->>'category_id'))::uuid,(tmap->>(x->>'tag_id'))::uuid FROM jsonb_array_elements(p->'category_tags') x;
  RETURN;
 END IF;
 definition:=public._demo_template_definition(p_slot,p);
 typ:=(definition->>'type')::game_type;stat:=(definition->>'status')::game_status;
 UPDATE games SET status='draft' WHERE id=p_id;
 DELETE FROM poll_sessions WHERE game_id=p_id;
 DELETE FROM questions WHERE game_id=p_id;
 UPDATE games SET name=p#>>'{game,name}',type=typ WHERE id=p_id;
 FOR q,qi IN SELECT value,ordinality::int FROM jsonb_array_elements(p->'questions') WITH ORDINALITY LOOP
  INSERT INTO questions(game_id,ord,text) VALUES(p_id,qi,q->>'text') RETURNING id INTO qid;
  qids:=array_append(qids,qid);
  FOR a,ai IN SELECT value,ordinality::int FROM jsonb_array_elements(coalesce(q->'answers','[]')) WITH ORDINALITY LOOP
   INSERT INTO answers(question_id,ord,text,fixed_points) VALUES(qid,ai,left(btrim(a->>'text'),17),coalesce((a->>'fixed_points')::int,0)) RETURNING id INTO aid;
   amap:=amap||jsonb_build_object(qi::text||':'||ai::text,aid);
  END LOOP;
  IF stat='poll_open' THEN
   INSERT INTO poll_sessions(game_id,question_id,question_ord,is_open) VALUES(p_id,qid,qi,true) RETURNING id INTO sid;
   sids:=array_append(sids,sid);
  END IF;
 END LOOP;
 IF stat='poll_open' THEN
  FOR v IN SELECT value FROM jsonb_array_elements(definition->'votes') LOOP
   qi:=(v->>'q')::int;
   IF typ='poll_text' THEN
    SELECT count(*) INTO off FROM poll_text_entries WHERE game_id=p_id AND question_id=qids[qi];
    FOR vi IN 1..(v->>'count')::int LOOP
     INSERT INTO poll_text_entries(game_id,poll_session_id,question_id,voter_token,answer_raw,answer_norm)
      VALUES(p_id,sids[qi],qids[qi],'demo_seed_v'||lpad((off+vi)::text,6,'0'),v->>'text',lower(regexp_replace(btrim(v->>'text'),'\s+',' ','g')));
    END LOOP;
   ELSE
    SELECT id,ord INTO aid,ai FROM answers WHERE question_id=qids[qi] AND text=v->>'text' ORDER BY ord LIMIT 1;
    SELECT count(*) INTO off FROM poll_votes WHERE game_id=p_id AND question_id=qids[qi];
    FOR vi IN 1..(v->>'count')::int LOOP
     INSERT INTO poll_votes(game_id,question_ord,answer_ord,voter_token,poll_session_id,question_id,answer_id)
      VALUES(p_id,qi,ai,'demo_seed_v'||lpad((off+vi)::text,6,'0'),sids[qi],qids[qi],aid);
    END LOOP;
   END IF;
  END LOOP;
 END IF;
 UPDATE games SET status=stat WHERE id=p_id;
END $$;


