--
-- Name: _display_is_default("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."_display_is_default"("d" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN d IS NULL OR jsonb_typeof(d) <> 'object' THEN true ELSE
    (jsonb_typeof(d->'colors') IS DISTINCT FROM 'object'
      OR (lower(d->'colors'->>'DOT') = '#d7ff3d'
        AND (lower(d->'colors'->>'A'), lower(d->'colors'->>'B'), lower(d->'colors'->>'BACKGROUND'))
          IN (('#c4002f', '#2a62ff', '#d21180'), ('#ff8c1a', '#138a50', '#152238'))))
    AND (NULLIF(d->>'theme', '') IS NULL
      OR (d->>'theme' = 'classic'
        AND lower(d->'colors'->>'A') = '#c4002f' AND lower(d->'colors'->>'B') = '#2a62ff'
        AND lower(d->'colors'->>'BACKGROUND') = '#d21180'))
  END
$$;


