--
-- Name: acquire_edit_lock("text", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acquire_edit_lock"("p_resource_type" "text", "p_resource_id" "uuid", "p_tab_id" "text", "p_context" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.acquire_edit_lock_mode(p_resource_type, p_resource_id, p_tab_id, p_context, 'exclusive');
$$;


--
-- Name: acquire_edit_lock_mode("text", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acquire_edit_lock_mode"("p_resource_type" "text", "p_resource_id" "uuid", "p_tab_id" "text", "p_context" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'exclusive'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_exists boolean := false;
  v_key text;
  v_owner uuid;
  v_row public.edit_locks;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;
  if coalesce(trim(p_tab_id), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'missing_tab_id');
  end if;
  if p_mode not in ('exclusive', 'shared') then
    return jsonb_build_object('ok', false, 'error', 'unknown_mode');
  end if;
  if p_resource_type not in ('game', 'logo', 'logos', 'base', 'base_question', 'base_folder', 'base_tag') then
    return jsonb_build_object('ok', false, 'error', 'unknown_resource_type');
  end if;
  v_exists := case p_resource_type
    when 'game' then exists (select 1 from public.games where id = p_resource_id)
    when 'logo' then exists (select 1 from public.user_logos where id = p_resource_id)
    when 'logos' then p_resource_id = v_uid
    when 'base' then exists (select 1 from public.question_bases where id = p_resource_id)
    when 'base_question' then exists (select 1 from public.qb_questions where id = p_resource_id)
    when 'base_folder' then exists (select 1 from public.qb_categories where id = p_resource_id)
    when 'base_tag' then exists (select 1 from public.qb_tags where id = p_resource_id)
    else false
  end;
  if not v_exists then
    return jsonb_build_object('ok', false, 'error', 'gone');
  end if;
  if not public.can_edit_locked_resource(p_resource_type, p_resource_id) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  -- serializacja zajmowania w obrębie zasobu; logo i pula logo użytkownika
  -- dzielą jeden klucz, bo zasady zgodności łączą je ze sobą.
  if p_resource_type = 'logo' then
    select user_id into v_owner from public.user_logos where id = p_resource_id;
    v_key := 'logos:' || v_owner::text;
  elsif p_resource_type = 'logos' then
    v_key := 'logos:' || p_resource_id::text;
  else
    v_key := p_resource_type || ':' || p_resource_id::text;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_key, 0));

  -- wygasłe trzymania innych kart tego zasobu znikają (zwalniają klucz
  -- wyłączny); wygasłe nie przeszkadzają też w edit_lock_blockers.
  delete from public.edit_locks
   where resource_type = p_resource_type
     and resource_id = p_resource_id
     and holder_tab_id <> p_tab_id
     and heartbeat_at < now() - public.edit_lock_ttl();

  select * into v_row
  from public.edit_lock_blockers(p_resource_type, p_resource_id, p_mode, p_tab_id)
  order by acquired_at
  limit 1;

  if found then
    return jsonb_build_object('ok', false, 'error', 'locked',
      'holder_user_id', v_row.holder_user_id, 'acquired_at', v_row.acquired_at,
      'blocker_type', v_row.resource_type, 'blocker_id', v_row.resource_id,  -- 479: + blocker_id
      'blocker_mode', v_row.mode, 'blocker_context', v_row.holder_context);
  end if;

  -- 522: otwarcie zasobu (nie odświeżenie własnej blokady) najpierw wpisuje
  -- czekającą aktualizację demo — w tej chwili nikt inny go nie trzyma.
  if not exists (select 1 from public.edit_locks
                  where resource_type = p_resource_type and resource_id = p_resource_id
                    and holder_tab_id = p_tab_id and heartbeat_at > now() - public.edit_lock_ttl()) then
    perform public._demo_apply_pending(p_resource_type, p_resource_id);
  end if;

  insert into public.edit_locks
    (resource_type, resource_id, holder_tab_id, holder_user_id, holder_context, mode, acquired_at, heartbeat_at)
  values
    (p_resource_type, p_resource_id, p_tab_id, v_uid, p_context, p_mode, now(), now())
  on conflict (resource_type, resource_id, holder_tab_id) do update
    set holder_user_id = excluded.holder_user_id,
        holder_context = excluded.holder_context,
        heartbeat_at = excluded.heartbeat_at,
        acquired_at = case
          when public.edit_locks.mode = excluded.mode
            then public.edit_locks.acquired_at
          else excluded.acquired_at
        end,
        mode = excluded.mode;

  return jsonb_build_object('ok', true, 'acquired', true);
end;
$$;


--
-- Name: acquire_edit_locks("jsonb", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acquire_edit_locks"("p_resources" "jsonb", "p_tab_id" "text", "p_context" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'exclusive'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
  v_res jsonb;
  v_fail jsonb;
  v_n int := 0;
BEGIN
  BEGIN
    FOR r IN SELECT DISTINCT ON (x->>'type', (x->>'id')::uuid)
                    x->>'type' AS type, (x->>'id')::uuid AS id,
                    coalesce(nullif(x->>'mode', ''), p_mode) AS mode  -- 479: tryb per zasób
               FROM jsonb_array_elements(coalesce(p_resources, '[]'::jsonb)) x
              ORDER BY x->>'type', (x->>'id')::uuid LOOP
      v_res := public.acquire_edit_lock_mode(r.type, r.id, p_tab_id, p_context, r.mode);
      IF NOT coalesce((v_res->>'ok')::boolean, false) THEN
        v_fail := v_res || jsonb_build_object('resource', jsonb_build_object('type', r.type, 'id', r.id, 'mode', r.mode));
        RAISE EXCEPTION 'edit_locks:refused';
      END IF;
      v_n := v_n + 1;
    END LOOP;
  EXCEPTION WHEN raise_exception THEN
    IF v_fail IS NOT NULL THEN RETURN v_fail; END IF;
    RAISE;
  END;
  RETURN jsonb_build_object('ok', true, 'count', v_n);
END;
$$;


--
-- Name: admin_demo_apply_batch(integer, "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_demo_apply_batch"("p_limit" integer DEFAULT 50, "p_after_update" "uuid" DEFAULT NULL::"uuid", "p_after_resource" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r record; st text; n jsonb := '{"updated":0,"edited":0,"removed":0,"waiting":0,"failed":0}'; last_u uuid; last_r uuid; cnt int := 0;
BEGIN
 IF p_limit < 1 OR p_limit > 200 THEN RAISE EXCEPTION 'admin_demo_bad_args'; END IF;
 FOR r IN SELECT update_id, resource_id FROM admin_demo_targets
   WHERE status='queued' AND (p_after_update IS NULL OR (update_id, resource_id) > (p_after_update, p_after_resource))
   ORDER BY update_id, resource_id LIMIT p_limit LOOP
  st := public._demo_apply_target(r.update_id, r.resource_id);
  IF st IS NOT NULL THEN n := jsonb_set(n, ARRAY[st], to_jsonb((n->>st)::int + 1)); END IF;
  last_u := r.update_id; last_r := r.resource_id; cnt := cnt + 1;
 END LOOP;
 RETURN n || jsonb_build_object('done', cnt < p_limit, 'after_update', last_u, 'after_resource', last_r,
  'queued', (SELECT count(*) FROM admin_demo_targets WHERE status='queued'));
END $$;


--
-- Name: admin_demo_preview("text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_demo_preview"("p_lang" "text", "p_slot" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE old jsonb; expected jsonb; kind text; n integer;
BEGIN
 IF p_lang NOT IN ('pl','en','uk') OR p_slot NOT IN ('base','logo_text','logo_draw','logo_image','prepared','poll_text_open','poll_text_closed','poll_text_draft','poll_points_open','poll_points_closed','poll_points_draft') THEN RAISE EXCEPTION 'invalid_demo_slot'; END IF;
 SELECT payload INTO old FROM demo_template_data WHERE lang=p_lang AND slot=p_slot;
 IF old IS NULL THEN RAISE EXCEPTION 'demo_template_not_found'; END IF;
 kind:=CASE WHEN p_slot='base' THEN 'base' WHEN p_slot LIKE 'logo_%' THEN 'logo' ELSE 'game' END;
 expected:=public._demo_template_definition(p_slot,old);
 SELECT count(*) INTO n FROM (
  SELECT id FROM games WHERE is_demo AND kind='game'
  UNION ALL SELECT id FROM user_logos WHERE is_demo AND kind='logo'
  UNION ALL SELECT id FROM question_bases WHERE is_demo AND kind='base'
 ) x WHERE public._demo_current_definition(kind,x.id)=expected;
 RETURN jsonb_build_object('ok',true,'eligible',n,'revision',encode(sha256(convert_to(old::text,'UTF8')),'hex'),'kind',kind,'definition',public._demo_template_definition(p_slot,p_payload));
END $$;


--
-- Name: admin_demo_replace("uuid", "text", "text", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_demo_replace"("p_request" "uuid", "p_lang" "text", "p_slot" "text", "p_payload" "jsonb", "p_revision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE old jsonb; check_result jsonb; upd uuid; kind text; old_def jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('admin-demo',0));
 SELECT id INTO upd FROM admin_demo_updates WHERE request_id=p_request;
 IF upd IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'id',upd,'already',true); END IF;
 SELECT payload INTO old FROM demo_template_data WHERE lang=p_lang AND slot=p_slot FOR UPDATE;
 IF old IS NULL OR encode(sha256(convert_to(old::text,'UTF8')),'hex') IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'demo_version_changed_refresh_preview'; END IF;
 check_result:=public.admin_demo_preview(p_lang,p_slot,p_payload);kind:=check_result->>'kind';
 IF check_result->'definition' IS NULL THEN RAISE EXCEPTION 'invalid_demo_payload'; END IF;
 old_def:=public._demo_template_definition(p_slot,old);
 INSERT INTO admin_demo_updates(request_id,lang,slot,old_payload,new_payload,old_definition) VALUES(p_request,p_lang,p_slot,old,p_payload,old_def) RETURNING id INTO upd;
 -- kopie czekające na starszą wersję tego demo: nowy wpis z ich oczekiwaną treścią
 INSERT INTO admin_demo_targets(update_id,kind,resource_id,expected_definition)
  SELECT upd,t.kind,t.resource_id,coalesce(t.expected_definition,u.old_definition)
  FROM admin_demo_targets t JOIN admin_demo_updates u ON u.id=t.update_id
  WHERE t.status='queued' AND u.lang=p_lang AND u.slot=p_slot AND u.id<>upd;
 UPDATE admin_demo_targets t SET status='superseded',message=''
  FROM admin_demo_updates u WHERE u.id=t.update_id AND t.status='queued' AND u.lang=p_lang AND u.slot=p_slot AND u.id<>upd;
 INSERT INTO admin_demo_targets(update_id,kind,resource_id)
  SELECT upd,kind,x.id FROM (SELECT id FROM games WHERE is_demo AND kind='game' UNION ALL SELECT id FROM user_logos WHERE is_demo AND kind='logo' UNION ALL SELECT id FROM question_bases WHERE is_demo AND kind='base') x
  WHERE public._demo_current_definition(kind,x.id)=old_def
  ON CONFLICT DO NOTHING;
 UPDATE demo_template_data SET payload=p_payload WHERE lang=p_lang AND slot=p_slot;
 RETURN jsonb_build_object('ok',true,'id',upd,'eligible',check_result->'eligible');
END $$;


--
-- Name: admin_theme_import_access_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_theme_import_access_list"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'user_id', a.user_id, 'username', p.username, 'email', p.email, 'granted_at', a.granted_at,
    'themes', (SELECT count(*) FROM public.user_display_themes t WHERE t.owner_id = a.user_id))
    ORDER BY a.granted_at), '[]'::jsonb)
  FROM public.theme_import_access a LEFT JOIN public.profiles p ON p.id = a.user_id
$$;


--
-- Name: admin_theme_import_access_set("text", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_theme_import_access_set"("p_login" "text", "p_enabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE prof public.profiles;
BEGIN
  SELECT * INTO prof FROM public.profiles
   WHERE lower(username) = lower(btrim(p_login)) OR lower(email) = lower(btrim(p_login))
   ORDER BY (lower(username) = lower(btrim(p_login))) DESC LIMIT 1;
  IF prof.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF prof.is_guest THEN RETURN jsonb_build_object('ok', false, 'error', 'guest'); END IF;
  IF p_enabled THEN
    INSERT INTO public.theme_import_access(user_id) VALUES (prof.id) ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.theme_import_access WHERE user_id = prof.id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'user_id', prof.id, 'username', prof.username, 'enabled', p_enabled);
END $$;


--
-- Name: agent_mail_window_counts(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."agent_mail_window_counts"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("przydzialy" bigint, "przydzialy_zuzyte" bigint, "przydzialy_niezuzyte" bigint, "przydzialy_niezuzyte_bez_testowych" bigint, "kolejka_powiadomien" bigint, "kolejka_wyslane" bigint, "kolejka_bledy" bigint, "kolejka_oczekujace" bigint, "kolejka_inne" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH w AS (
    SELECT p_from AS f, least(p_to, p_from + interval '1 day') AS t
  ), a AS (
    SELECT al.* FROM public.mail_notification_allocations al, w WHERE al.created_at >= w.f AND al.created_at < w.t
  ), q AS (
    SELECT mq.* FROM public.mail_queue mq, w WHERE mq.created_at >= w.f AND mq.created_at < w.t
  )
  SELECT
    (SELECT count(*) FROM a),
    (SELECT count(*) FROM a WHERE consumed_at IS NOT NULL),
    (SELECT count(*) FROM a WHERE consumed_at IS NULL),
    (SELECT count(*) FROM a WHERE consumed_at IS NULL
       AND owner_id NOT IN (SELECT user_id FROM public.stats_exclusions_effective)),
    (SELECT count(*) FROM q WHERE created_by IS NOT NULL),
    (SELECT count(*) FROM q WHERE created_by IS NOT NULL AND status = 'sent'),
    (SELECT count(*) FROM q WHERE created_by IS NOT NULL AND status = 'failed'),
    (SELECT count(*) FROM q WHERE created_by IS NOT NULL AND status IN ('pending', 'sending')),
    (SELECT count(*) FROM q WHERE created_by IS NULL);
$$;


--
-- Name: answers_rules_state_stmt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."answers_rules_state_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ids uuid[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct q.game_id) into v_ids
    from new_rows r join public.questions q on q.id = r.question_id;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct q.game_id) into v_ids
    from old_rows r join public.questions q on q.id = r.question_id;
  else
    select array_agg(distinct q.game_id) into v_ids
    from (select question_id from new_rows union select question_id from old_rows) r
    join public.questions q on q.id = r.question_id;
  end if;
  if v_ids is not null then
    perform public.games_rules_state_refresh(v_ids);
  end if;
  return null;
end;
$$;


--
-- Name: app_ratings_after_unlink(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_ratings_after_unlink"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_guest boolean;
BEGIN
  SELECT p.is_guest INTO v_guest FROM public.profiles p WHERE p.id = OLD.user_id;
  IF NOT coalesce(v_guest, NEW.from_guest)
     OR EXISTS (SELECT 1 FROM public.stats_exclusions_effective e WHERE e.user_id = OLD.user_id) THEN
    DELETE FROM public.app_ratings WHERE id = NEW.id;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: app_ratings_set_from_guest(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."app_ratings_set_from_guest"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.user_id IS NULL THEN
    NEW.from_guest := CASE WHEN TG_OP = 'UPDATE' THEN OLD.from_guest ELSE false END;
  ELSE
    NEW.from_guest := coalesce((SELECT p.is_guest FROM public.profiles p WHERE p.id = NEW.user_id), false);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: are_friends("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."are_friends"("a" "uuid", "b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.friendships f
    WHERE f.status = 'active'
      AND ((f.requester_id = a AND f.addressee_id = b)
        OR (f.requester_id = b AND f.addressee_id = a))
  )
$$;


--
-- Name: assert_game_answers_minmax(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assert_game_answers_minmax"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  qn int;
  bad_q int;
  an int;
begin
  -- Walidujemy tylko gdy zmieniasz status na poll_open (start) albo ready (zamykanie)
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if new.status not in ('poll_open'::game_status, 'poll_stopped'::game_status, 'ready'::game_status) then
    return new;
  end if;

  -- gra preparowana nie ma sondażu, więc nie blokuj statusów z tej funkcji
  if new.type = 'prepared'::game_type then
    return new;
  end if;

  -- >= 10 pytań zawsze dla poll_text i poll_points
  select count(*) into qn
  from public.questions
  where game_id = new.id;

  if qn < 10 then
    raise exception 'assert_game_answers_minmax: need >=10 questions (have %)', qn;
  end if;

  -- poll_points: każde pytanie musi mieć 3..6 odpowiedzi (dla startu i zamknięcia)
  if new.type = 'poll_points'::game_type then
    select q.ord into bad_q
    from public.questions q
    where q.game_id = new.id
      and (
        (select count(*) from public.answers a where a.question_id = q.id) < 3
        or
        (select count(*) from public.answers a where a.question_id = q.id) > 6
      )
    order by q.ord
    limit 1;

    if bad_q is not null then
      select count(*) into an
      from public.answers a
      join public.questions q on q.id = a.question_id
      where q.game_id = new.id and q.ord = bad_q;

      raise exception 'assert_game_answers_minmax: question % must have 3..6 answers (have %)', bad_q, an;
    end if;
  end if;

  -- poll_text: tu nie walidujemy liczby odpowiedzi (bo w trakcie to teksty od ludzi),
  -- jedynie >=10 pytań.

  return new;
end $$;


