--
-- Name: poll_task_resolve("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_task_resolve"("p_token" "uuid", "p_email" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  t record;
  u uuid;
  requires_auth boolean := false;
  needs_email boolean := false;
  registered uuid;
  change_result text;
BEGIN
  u := auth.uid();

  SELECT
    pt.id,
    pt.owner_id,
    pt.recipient_user_id,
    pt.recipient_email,
    pt.game_id,
    pt.poll_type,
    pt.share_key_poll,
    pt.status,
    pt.opened_at,
    pt.done_at,
    pt.declined_at,
    pt.cancelled_at,
    g.status::text AS game_status, -- E11b
    g.owner_id AS game_owner, g.type::text AS game_type,
    g.share_key_poll AS game_key -- E11b
  INTO t
  FROM public.poll_tasks pt
  LEFT JOIN public.games g ON g.id = pt.game_id
  WHERE pt.token = p_token
  LIMIT 1;

  IF t.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  -- niedostępne u odbiorcy (declined/cancelled), oraz po wykonaniu
  IF t.status IN ('declined','cancelled') OR t.declined_at IS NOT NULL OR t.cancelled_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_or_unavailable_token');
  END IF;

  IF t.status = 'done' OR t.done_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_done');
  END IF;

  -- E11b: zaproszenie ważne tylko przy bieżącym kluczu gry i otwartej ankiecie
  IF t.game_key IS NULL OR t.owner_id IS DISTINCT FROM t.game_owner
     OR t.poll_type IS DISTINCT FROM t.game_type OR t.game_key <> t.share_key_poll
     OR t.game_status NOT IN ('poll_open', 'poll_stopped', 'ready') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;
  IF t.game_status = 'poll_stopped' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'poll_stopped');
  END IF;
  IF t.game_status = 'ready' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'poll_closed');
  END IF;

  -- jeżeli task jest przypisany do user_id: wymagamy zgodności sesji
  IF t.recipient_user_id IS NOT NULL THEN
    IF u IS NULL THEN
      requires_auth := true;
    ELSIF u <> t.recipient_user_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_or_unavailable_token');
    END IF;
  END IF;

  IF t.recipient_user_id IS NULL THEN
    registered:=public._poll_registered_uid(t.recipient_email);
    IF registered IS NOT NULL THEN
      IF u IS NULL THEN requires_auth := true;
      ELSIF u <> registered THEN RETURN jsonb_build_object('ok',false,'error','invalid_or_unavailable_token'); END IF;
    END IF;
  END IF;

  -- jeżeli task jest e-mailowy: e-mail może być potrzebny do późniejszego UI/komunikatu
  IF t.recipient_user_id IS NULL AND t.recipient_email IS NULL THEN
    -- przypadek "czysty e-mail": oczekujemy podania e-mail w UI
    IF p_email IS NULL OR btrim(p_email) = '' THEN
      needs_email := true;
    END IF;
  END IF;

  IF NOT requires_auth THEN
    change_result:=public._poll_task_change(p_token,'open');
    IF change_result<>'ok' THEN RETURN jsonb_build_object('ok',false,'error',change_result); END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', 'task',
    'task_id', t.id,
    'game_id', t.game_id,
    'poll_type', t.poll_type,
    'key', t.share_key_poll,
    'voter_token', public.poll_task_voter_token(t.id),
    'requires_auth', requires_auth,
    'needs_email', needs_email,
    'recipient_email', COALESCE(t.recipient_email, NULLIF(btrim(p_email), ''))
  );
END;
$$;


--
-- Name: poll_task_voter_token("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_task_voter_token"("p_task_id" "uuid") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT 'task:' || p_task_id::text
$$;


--
-- Name: poll_tasks_touch_status_ts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_tasks_touch_status_ts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    if new.status = 'opened' and new.opened_at is null then
      new.opened_at := now();
    end if;

    if new.status = 'done' and new.done_at is null then
      new.done_at := now();
    end if;

    if new.status = 'declined' and new.declined_at is null then
      new.declined_at := now();
    end if;

    if new.status = 'cancelled' and new.cancelled_at is null then
      new.cancelled_at := now();
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: poll_text_submit("uuid", "text", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_text_submit"("p_game_id" "uuid", "p_key" "text", "p_question_id" "uuid", "p_voter_token" "text", "p_answer_raw" "text", "p_answer_norm" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  g public.games%rowtype;
  s_id uuid;
  v_raw text := btrim(coalesce(p_answer_raw, ''));
begin
  perform public._poll_assert_voter(p_game_id, p_key, p_voter_token);
  select * into g from public.games where id = p_game_id;
  if not found then raise exception 'Game not found'; end if;
  if g.share_key_poll <> p_key then raise exception 'Invalid poll key'; end if;
  if g.type <> 'poll_text'::game_type then raise exception 'Wrong game type'; end if;
  if g.status <> 'poll_open'::game_status then raise exception 'Poll is not open'; end if;
  if char_length(v_raw) not between 1 and 17 then raise exception 'invalid_answer'; end if;

  select ps.id into s_id
  from public.poll_sessions ps
  where ps.game_id = p_game_id and ps.question_id = p_question_id and ps.is_open = true
  order by ps.created_at desc limit 1;
  if s_id is null then raise exception 'No open session'; end if;

  insert into public.poll_text_entries (game_id, poll_session_id, question_id, voter_token, answer_raw, answer_norm)
  values (p_game_id, s_id, p_question_id, p_voter_token, v_raw,
          lower(regexp_replace(coalesce(nullif(btrim(p_answer_norm), ''), v_raw), '\s+', ' ', 'g')));
end;
$$;


--
-- Name: poll_text_submit_batch("uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_text_submit_batch"("p_game_id" "uuid", "p_key" "text", "p_voter_token" "text", "p_items" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  it jsonb;
begin
  perform public._poll_assert_voter(p_game_id,p_key,p_voter_token);
  if jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items must be a JSON array';
  end if;

  for it in
    select * from jsonb_array_elements(p_items)
  loop
    perform public.poll_text_submit(
      p_game_id      => p_game_id,
      p_key          => p_key,
      p_question_id  => (it->>'question_id')::uuid,
      p_voter_token  => p_voter_token,
      p_answer_raw   => it->>'answer_raw',
      p_answer_norm  => it->>'answer_norm'
    );
  end loop;
  perform public._poll_task_finish_batch(p_game_id,p_key,p_voter_token);

end;
$$;


--
-- Name: poll_text_tally_apply("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_text_tally_apply"("p_game_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type text;
  v_status text;
  v_chk jsonb;
  v_n int;
  q record;
  item jsonb;
  v_all jsonb := '{}'::jsonb;
  v_ans jsonb;
  v_sum bigint;
BEGIN
  PERFORM public._poll_assert_owner(p_game_id);

  SELECT g.type::text, g.status::text INTO v_type, v_status
  FROM public.games g WHERE g.id = p_game_id FOR UPDATE;
  IF v_type <> 'poll_text' THEN RAISE EXCEPTION 'wrong_type'; END IF;
  IF v_status <> 'poll_stopped' THEN RAISE EXCEPTION 'poll_not_stopped'; END IF;
  IF jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_payload'; END IF;

  v_chk := public.game_poll_close_check(p_game_id);
  IF NOT coalesce((v_chk->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'poll_close_blocked:%:%', coalesce(v_chk->>'code', 'unknownType'),
      coalesce(v_chk->'params'->>'n', '') USING ERRCODE = 'P0001';
  END IF;
  v_n := (v_chk->'params'->>'n')::int;

  -- najpierw policz i zwaliduj wszystkie pytania, dopiero potem zapisuj
  FOR q IN SELECT id, ord FROM public.questions WHERE game_id = p_game_id ORDER BY ord LOOP
    SELECT i INTO item FROM jsonb_array_elements(p_payload->'items') AS i
    WHERE i->>'question_id' = q.id::text LIMIT 1;

    -- liczby głosów z klienta nie mogą przekroczyć pełnych ankiet (nieaktualny podgląd)
    SELECT coalesce(sum(CASE WHEN jsonb_typeof(a->'count') = 'number' THEN greatest(0, floor((a->>'count')::numeric)) ELSE 0 END), 0)
      INTO v_sum FROM jsonb_array_elements(CASE WHEN jsonb_typeof(item->'answers') = 'array' THEN item->'answers' ELSE '[]' END) a;
    IF v_sum > v_n THEN
      RAISE EXCEPTION 'poll_close_blocked:tallyStale:%', q.ord USING ERRCODE = 'P0001';
    END IF;

    BEGIN
      SELECT coalesce(jsonb_agg(jsonb_build_object('text', c.atext, 'points', c.points) ORDER BY c.ord), '[]'::jsonb)
        INTO v_ans
      FROM public._poll_text_tally_select(item->'answers', item->'selected', v_n) c;
    EXCEPTION WHEN raise_exception THEN
      IF SQLERRM = 'tally_selection' THEN
        RAISE EXCEPTION 'poll_close_blocked:tallySelection:%', q.ord USING ERRCODE = 'P0001';
      END IF;
      RAISE;
    END;

    IF item IS NULL OR jsonb_array_length(v_ans) < 3 THEN
      RAISE EXCEPTION 'poll_close_blocked:closeMinText:%', q.ord USING ERRCODE = 'P0001';
    END IF;
    v_all := v_all || jsonb_build_object(q.id::text, v_ans);
  END LOOP;

  FOR q IN SELECT id FROM public.questions WHERE game_id = p_game_id LOOP
    DELETE FROM public.answers WHERE question_id = q.id;
    INSERT INTO public.answers (question_id, ord, text, fixed_points)
    SELECT q.id, a.i, a.x->>'text', (a.x->>'points')::int
    FROM jsonb_array_elements(v_all->(q.id::text)) WITH ORDINALITY AS a(x, i);
  END LOOP;

  PERFORM public._poll_finish_tally(p_game_id);
  RETURN jsonb_build_object('ok', true, 'status', 'ready');
END $$;


--
-- Name: poll_text_tally_draft_get("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_text_tally_draft_get"("p_game_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  d record;
BEGIN
  PERFORM public._poll_assert_owner(p_game_id);

  SELECT g.status::text INTO v_status FROM public.games g WHERE g.id = p_game_id;
  IF v_status <> 'poll_stopped' THEN
    RETURN jsonb_build_object('draft', NULL, 'saved_at', NULL);
  END IF;

  SELECT t.draft, t.updated_at INTO d FROM public.poll_tally_drafts t WHERE t.game_id = p_game_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('draft', NULL, 'saved_at', NULL);
  END IF;
  RETURN jsonb_build_object('draft', d.draft, 'saved_at', d.updated_at);
END $$;


--
-- Name: poll_text_tally_draft_save("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_text_tally_draft_save"("p_game_id" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type text;
  v_status text;
  v_at timestamptz := now();
BEGIN
  PERFORM public._poll_assert_owner(p_game_id);

  SELECT g.type::text, g.status::text INTO v_type, v_status
  FROM public.games g WHERE g.id = p_game_id FOR UPDATE;

  IF v_type <> 'poll_text' THEN
    RAISE EXCEPTION 'wrong_type';
  END IF;
  IF v_status <> 'poll_stopped' THEN
    RAISE EXCEPTION 'poll_not_stopped';
  END IF;

  IF p_draft IS NULL OR p_draft = 'null'::jsonb THEN
    DELETE FROM public.poll_tally_drafts WHERE game_id = p_game_id;
    RETURN jsonb_build_object('ok', true, 'saved_at', NULL);
  END IF;
  IF octet_length(p_draft::text) > 524288 THEN
    RAISE EXCEPTION 'draft_too_large';
  END IF;

  INSERT INTO public.poll_tally_drafts (game_id, draft, updated_at)
  VALUES (p_game_id, p_draft, v_at)
  ON CONFLICT (game_id) DO UPDATE SET draft = excluded.draft, updated_at = excluded.updated_at;

  RETURN jsonb_build_object('ok', true, 'saved_at', v_at);
END $$;


--
-- Name: poll_vote_game("uuid", "text", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."poll_vote_game"("p_game_id" "uuid", "p_key" "text", "p_question_id" "uuid", "p_answer_id" "uuid", "p_voter_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  g public.games;
  sess public.poll_sessions;
begin
  perform public._poll_assert_voter(p_game_id,p_key,p_voter_token);
  select * into g from public.games where id = p_game_id;
  if not found then raise exception 'not found'; end if;
  if g.share_key_poll <> p_key then raise exception 'forbidden'; end if;
  if g.status <> 'poll_open' then raise exception 'poll closed'; end if;

  -- aktywna sesja per pytanie (poll_sessions już masz)
  select * into sess
  from public.poll_sessions
  where game_id = p_game_id and question_id = p_question_id and is_open = true
  order by created_at desc
  limit 1;

  if not found then
    insert into public.poll_sessions(game_id, question_id, is_open)
    values (p_game_id, p_question_id, true)
    returning * into sess;
  end if;

  insert into public.poll_votes(poll_session_id, voter_token, answer_id)
  values (sess.id, p_voter_token, p_answer_id)
  on conflict (poll_session_id, voter_token)
  do update set answer_id = excluded.answer_id;
end $$;


--
-- Name: polls_hub_anon_voters("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_anon_voters"("p_game_id" "uuid", "p_poll_type" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  qn int := 0;
  tok_cnt int := 0;
  legacy_rows int := 0;
  legacy_est int := 0;
  base_cnt int := 0;

  fp_sum numeric := 0;
  fp_est int := 0;
BEGIN
  SELECT count(*)::int INTO qn
  FROM public.questions
  WHERE game_id = p_game_id;

  IF p_poll_type = 'poll_points' THEN
    -- NOWE: tokeny anonimowe (per gra)
    SELECT count(DISTINCT v.voter_token)::int INTO tok_cnt
    FROM public.poll_votes v
    WHERE v.game_id = p_game_id
      AND v.voter_user_id IS NULL
      AND v.voter_token IS NOT NULL
      AND v.voter_token <> ''
      AND v.voter_token NOT LIKE 'task:%';

    -- STARE: brak tokena / pusty token (legacy)
    SELECT count(*)::int INTO legacy_rows
    FROM public.poll_votes v
    WHERE v.game_id = p_game_id
      AND v.voter_user_id IS NULL
      AND (v.voter_token IS NULL OR v.voter_token = '');

  ELSIF p_poll_type = 'poll_text' THEN
    -- NOWE: tokeny anonimowe (per gra)
    SELECT count(DISTINCT e.voter_token)::int INTO tok_cnt
    FROM public.poll_text_entries e
    WHERE e.game_id = p_game_id
      AND e.voter_user_id IS NULL
      AND e.voter_token IS NOT NULL
      AND e.voter_token <> ''
      AND e.voter_token NOT LIKE 'task:%';

    -- STARE: brak tokena / pusty token (legacy)
    SELECT count(*)::int INTO legacy_rows
    FROM public.poll_text_entries e
    WHERE e.game_id = p_game_id
      AND e.voter_user_id IS NULL
      AND (e.voter_token IS NULL OR e.voter_token = '');
  ELSE
    tok_cnt := 0;
    legacy_rows := 0;
  END IF;

  -- legacy est: total legacy rows / liczba pytań (ceil), min 1 jeśli cokolwiek jest
  IF legacy_rows > 0 AND qn > 0 THEN
    legacy_est := GREATEST(1, CEIL(legacy_rows::numeric / qn::numeric))::int;
  ELSE
    legacy_est := 0;
  END IF;

  base_cnt := tok_cnt + legacy_est;

  -- ✅ fallback: jeśli dalej 0 -> fixed_points sum / liczba pytań
  IF base_cnt = 0 AND qn > 0 THEN
    SELECT coalesce(sum(a.fixed_points), 0)::numeric INTO fp_sum
    FROM public.answers a
    JOIN public.questions q ON q.id = a.question_id
    WHERE q.game_id = p_game_id;

    IF fp_sum > 0 THEN
      fp_est := CEIL(fp_sum / qn::numeric)::int;
      base_cnt := fp_est;
    END IF;
  END IF;

  RETURN base_cnt;
END;
$$;


--
-- Name: polls_hub_can_close("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_can_close"("p_game_id" "uuid", "p_poll_type" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Nie zamykamy jeśli są jeszcze aktywne taski (niezagłosowane): X != Y
  IF EXISTS (
    SELECT 1
    FROM public.poll_tasks t
    WHERE t.owner_id = auth.uid()
      AND t.game_id = p_game_id
      AND t.done_at IS NULL
      AND t.declined_at IS NULL
      AND t.cancelled_at IS NULL
  ) THEN
    RETURN FALSE;
  END IF;

  RETURN CASE
    WHEN p_poll_type = 'poll_points' THEN public.polls_hub_can_close_poll_points(p_game_id)
    WHEN p_poll_type = 'poll_text'   THEN public.polls_hub_can_close_poll_text(p_game_id)
    ELSE FALSE
  END;
END;
$$;


--
-- Name: polls_hub_can_close_poll_points("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_can_close_poll_points"("p_game_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  q record;
  sid uuid;
  strong_cnt int;
BEGIN
  FOR q IN
    SELECT id FROM public.questions WHERE game_id = p_game_id ORDER BY ord
  LOOP
    -- ostatnia sesja dla pytania (jak w polls.js)
    SELECT ps.id
      INTO sid
    FROM public.poll_sessions ps
    WHERE ps.game_id = p_game_id AND ps.question_id = q.id
    ORDER BY ps.created_at DESC
    LIMIT 1;

    IF sid IS NULL THEN
      RETURN FALSE;
    END IF;

    /*
      poll.js:
        - bierzemy tylko votes z answer_id != null
        - counts tylko dla odpowiedzi z count>0
        - normalizacja do 100 przez floor + największe reszty (diff>0)
        - strong = points>=3
        - strong_cnt>=3
    */
    WITH counts AS (
      SELECT v.answer_id, count(*)::int AS cnt
      FROM public.poll_votes v
      WHERE v.game_id = p_game_id
        AND v.question_id = q.id
        AND v.poll_session_id = sid
        AND v.answer_id IS NOT NULL
      GROUP BY v.answer_id
      HAVING count(*) > 0
    ),
    total AS (
      SELECT sum(cnt)::numeric AS s FROM counts
    ),
    raw AS (
      SELECT
        answer_id,
        cnt,
        (100 * cnt::numeric) / NULLIF((SELECT s FROM total), 0) AS pct
      FROM counts
    ),
    floored AS (
      SELECT
        answer_id,
        cnt,
        pct,
        floor(pct)::int AS pts,
        (pct - floor(pct)) AS frac
      FROM raw
    ),
    sum_floor AS (
      SELECT coalesce(sum(pts), 0)::int AS s FROM floored
    ),
    diff AS (
      SELECT (100 - (SELECT s FROM sum_floor))::int AS d
    ),
    ranked AS (
      SELECT
        f.*,
        row_number() OVER (ORDER BY f.frac DESC, f.answer_id) AS rn
      FROM floored f
    ),
    distributed AS (
      SELECT
        answer_id,
        (pts + CASE WHEN (SELECT d FROM diff) > 0 AND rn <= (SELECT d FROM diff) THEN 1 ELSE 0 END)::int AS p_final
      FROM ranked
    )
    SELECT count(*)::int
      INTO strong_cnt
    FROM distributed
    WHERE p_final >= 3;

    -- jeśli nie ma żadnych głosów (counts puste) => distributed puste => strong_cnt=0 => FALSE
    IF COALESCE(strong_cnt, 0) < 3 THEN
      RETURN FALSE;
    END IF;
  END LOOP;

  RETURN TRUE;
END;
$$;


--
-- Name: polls_hub_can_close_poll_text("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_can_close_poll_text"("p_game_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  q record;
  sid uuid;
  uniq_cnt int;
BEGIN
  FOR q IN
    SELECT id FROM public.questions WHERE game_id = p_game_id ORDER BY ord
  LOOP
    SELECT ps.id
      INTO sid
    FROM public.poll_sessions ps
    WHERE ps.game_id = p_game_id AND ps.question_id = q.id
    ORDER BY ps.created_at DESC
    LIMIT 1;

    IF sid IS NULL THEN
      RETURN FALSE;
    END IF;

    SELECT count(DISTINCT btrim(e.answer_norm))::int
      INTO uniq_cnt
    FROM public.poll_text_entries e
    WHERE e.game_id = p_game_id
      AND e.question_id = q.id
      AND e.poll_session_id = sid
      AND NULLIF(btrim(e.answer_norm), '') IS NOT NULL;

    IF COALESCE(uniq_cnt, 0) < 3 THEN
      RETURN FALSE;
    END IF;
  END LOOP;

  RETURN TRUE;
END;
$$;


--
-- Name: polls_hub_subscriber_remove("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_subscriber_remove"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_sub public.poll_subscriptions%rowtype;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth required');
  end if;

  select * into v_sub
  from public.poll_subscriptions
  where id = p_id
    and owner_id = v_uid
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not found');
  end if;

  PERFORM public._poll_identity_email_refs(ARRAY[v_sub.subscriber_email],ARRAY[v_uid,v_sub.registered_user_id,v_sub.registered_user_id]);
  PERFORM public._subscriber_pair_lock(v_uid,v_sub.subscriber_email);
  SELECT * INTO v_sub FROM public.poll_subscriptions WHERE id=p_id AND owner_id=v_uid FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not found'); END IF;

  -- 424: oczekująca propozycja znajomości z tej subskrypcji zostaje
  update public.friendships
  set source_subscription_id = null
  where source_subscription_id = v_sub.id
    and status = 'pending'
    and cancelled_at is null;

  update public.poll_subscriptions
  set status = 'cancelled',
      cancelled_at = now()
  where id = p_id;

  -- E11b: usunięcie subskrybenta wycofuje jego czekające zaproszenia do ankiet tego właściciela
  delete from public.poll_tasks pt
  where pt.owner_id = v_uid
    and pt.status in ('pending', 'opened')
    and (pt.source_subscription_id=v_sub.id OR (pt.source_kind='game' AND ((v_sub.registered_user_id is not null and pt.recipient_user_id=v_sub.registered_user_id) OR (v_sub.subscriber_email is not null and public._norm_email(pt.recipient_email)=public._norm_email(v_sub.subscriber_email)))));

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: polls_hub_subscriber_resend("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_subscriber_resend"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
 FOR attempt IN 1..1000 LOOP
  BEGIN
 result:=public._mail_original361_polls_hub_subscriber_resend(p_id);
 IF result->>'ok'='true' AND result->>'to' IS NOT NULL THEN PERFORM public._mail_allocate_notification('subscription',p_id,'poll:resend'); END IF;
 RETURN result;
  EXCEPTION WHEN lock_not_available THEN
   IF attempt=1000 THEN RAISE; END IF;
  END;
  PERFORM pg_sleep(.01);
 END LOOP;
END $$;


--
-- Name: polls_hub_task_decline("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_task_decline"("p_task_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE tok uuid;
BEGIN
 SELECT token INTO tok FROM public.poll_tasks WHERE id=p_task_id AND recipient_user_id=auth.uid();
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN public._poll_task_change(tok,'decline')='ok';
END; $$;


--
-- Name: polls_hub_tasks_mark_emailed("uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_hub_tasks_mark_emailed"("p_task_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_n integer := 0;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'auth required');
  end if;

  update public.poll_tasks
  set email_sent_at = now(),
      email_send_count = email_send_count + 1
  where owner_id = v_uid
    and id = any(coalesce(p_task_ids, array[]::uuid[]))
    and (recipient_email is not null or recipient_user_id is not null);

  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'updated', v_n);
end;
$$;


--
-- Name: polls_vote_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."polls_vote_counts"() RETURNS TABLE("game_id" "uuid", "status" "text", "votes" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT g.id, g.status::text,
         CASE g.type
           WHEN 'poll_points' THEN
             (SELECT count(DISTINCT v.voter_token)::integer FROM public.poll_votes v WHERE v.game_id = g.id)
           ELSE
             (SELECT count(DISTINCT e.voter_token)::integer FROM public.poll_text_entries e WHERE e.game_id = g.id)
         END
  FROM public.games g
  WHERE g.owner_id = auth.uid()
    AND g.type IN ('poll_text', 'poll_points')
    AND g.status IN ('poll_open', 'poll_stopped');
$$;


--
-- Name: profile_login_to_email("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."profile_login_to_email"("p_login" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v text;
begin
  v := trim(coalesce(p_login, ''));
  if v = '' then
    return null;
  end if;

  if position('@' in v) > 0 then
    return lower(v);
  end if;

  select lower(u.email)
  into v
  from public.profiles p
  join auth.users u on u.id = p.id
  where lower(p.username) = lower(v)
  limit 1;

  if v is null then
    select lower(email)
    into v
    from public.profiles
    where lower(username) = lower(p_login)
    limit 1;
  end if;

  return v;
end;
$$;


--
-- Name: profiles_block_noaccount_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."profiles_block_noaccount_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.email IS NOT NULL AND lower(btrim(NEW.email)) ~ '^e2e\+' AND NOT EXISTS (
    SELECT 1 FROM public.e2e_identities i
    WHERE i.role IN ('standard','disposable','dedicated') AND lower(btrim(NEW.email)) = i.email
  ) THEN
    RAISE EXCEPTION 'e2e address without account identity: %', NEW.email USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: profiles_reserve_test_username(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."profiles_reserve_test_username"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE reason text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.username IS NOT DISTINCT FROM OLD.username THEN RETURN NEW; END IF;
 reason:=public.reserved_username_reason(NEW.username);
 IF reason IS NULL THEN RETURN NEW; END IF;
 -- 460: e2e.<role><NN> tylko dla konta o adresie tej tożsamości
 IF reason='test' AND EXISTS (
 SELECT 1 FROM public.e2e_identities i JOIN auth.users u ON u.id=NEW.id
 WHERE i.name=lower(btrim(NEW.username)) AND i.role IN ('standard','disposable','dedicated')
 AND lower(u.email) IN (i.email, replace(i.email,'@','.new@'))
 ) THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM public.reserved_username_accounts a WHERE a.user_id=NEW.id AND a.username=lower(btrim(NEW.username))) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'username unavailable' USING ERRCODE='23505';
 RETURN NEW;
END $$;


--
-- Name: push_admin_event("text", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_admin_event"("p_event" "text", "p_vars" "jsonb" DEFAULT '{}'::"jsonb", "p_urgency" "text" DEFAULT 'normal'::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id bigint; v_event text := p_event; v_vars jsonb := coalesce(p_vars, '{}'); v_n integer;
  v_recent public.push_outbox;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE app = 'admin') THEN RETURN NULL; END IF;
  IF p_event IN ('mail', 'ticket') THEN
    SELECT * INTO v_recent FROM public.push_outbox
     WHERE app = 'admin' AND event = p_event AND created_at > now() - interval '5 minutes'
     ORDER BY id DESC LIMIT 1 FOR UPDATE SKIP LOCKED;
    IF FOUND THEN
      IF v_recent.sent_at IS NULL THEN
        -- jeszcze nie wysłane: jedno powiadomienie z licznikiem
        UPDATE public.push_outbox
           SET vars = vars || jsonb_build_object('n', greatest(
                 coalesce((vars->>'n')::int, 1) + 1, coalesce((v_vars->>'n')::int, 0)))
         WHERE id = v_recent.id;
        RETURN v_recent.id;
      END IF;
      RETURN NULL; -- wysłane przed chwilą: następne najwcześniej po 5 minutach
    END IF;
  END IF;
  IF p_event = 'job_error' THEN
    SELECT count(*) + 1 INTO v_n FROM public.push_outbox
     WHERE app = 'admin' AND event IN ('job_error','job_error_repeat')
       AND vars->>'what' IS NOT DISTINCT FROM v_vars->>'what'
       AND created_at > now() - interval '1 hour';
    IF v_n >= 3 THEN
      v_event := 'job_error_repeat';
      v_vars := v_vars || jsonb_build_object('n', v_n,
        'since', (SELECT min(created_at) FROM public.push_outbox WHERE app = 'admin'
                   AND event IN ('job_error','job_error_repeat') AND vars->>'what' IS NOT DISTINCT FROM v_vars->>'what'
                   AND created_at > now() - interval '1 hour'));
    END IF;
  END IF;
  INSERT INTO public.push_outbox (app, event, category, vars, ttl, urgency)
  VALUES ('admin', v_event, public.push_event_category('admin', v_event), v_vars,
          CASE WHEN v_event LIKE 'job_error%' THEN 3600 ELSE 86400 END,
          CASE WHEN v_event LIKE 'job_error%' THEN 'high' ELSE coalesce(p_urgency, 'normal') END)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: push_admin_get("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_admin_get"("p_endpoint" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'subscribed', EXISTS (SELECT 1 FROM public.push_subscriptions WHERE endpoint = p_endpoint AND app = 'admin'),
    'kinds', coalesce((SELECT to_jsonb(kinds) FROM public.push_subscriptions WHERE endpoint = p_endpoint AND app = 'admin'), '[]'::jsonb),
    'devices', (SELECT count(*) FROM public.push_subscriptions WHERE app = 'admin'),
    'recent', coalesce((SELECT jsonb_agg(r ORDER BY r->>'created_at' DESC) FROM (
       SELECT jsonb_build_object('event', event, 'created_at', created_at, 'sent_at', sent_at,
         'delivered', delivered, 'failed', failed, 'error', last_error) AS r
       FROM public.push_outbox WHERE app = 'admin' ORDER BY id DESC LIMIT 20) x), '[]'::jsonb))
$$;


--
-- Name: push_admin_subscribe("text", "text", "text", "text"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_admin_subscribe"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_kinds" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_rows integer;
BEGIN
  IF NOT public.push_endpoint_allowed(p_endpoint) THEN RETURN jsonb_build_object('ok', false, 'error', 'endpoint_not_allowed'); END IF;
  IF p_kinds IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(p_kinds) k WHERE k NOT IN ('mail','ticket','market','collect','errors')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_kinds');
  END IF;
  INSERT INTO public.push_subscriptions AS s (app, user_id, endpoint, p256dh, auth, lang, kinds, updated_at)
  VALUES ('admin', NULL, p_endpoint, p_p256dh, p_auth, 'pl', coalesce(p_kinds, '{}'), clock_timestamp())
  ON CONFLICT (endpoint) DO UPDATE SET p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth,
    kinds = EXCLUDED.kinds, updated_at = clock_timestamp(), fail_count = 0
    WHERE s.app = 'admin';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'endpoint_taken'); END IF;
  DELETE FROM public.push_subscriptions WHERE id IN (
    SELECT id FROM public.push_subscriptions WHERE app = 'admin' ORDER BY updated_at DESC OFFSET 10);
  RETURN jsonb_build_object('ok', true);
END $$;


--
-- Name: push_admin_test(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_admin_test"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object('ok', true, 'id', public.push_admin_event('test', '{}'::jsonb, 'high'))
$$;


--
-- Name: push_admin_unsubscribe("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_admin_unsubscribe"("p_endpoint" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH d AS (DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND app = 'admin' RETURNING 1)
  SELECT jsonb_build_object('ok', true, 'removed', (SELECT count(*) FROM d))
$$;


--
-- Name: push_endpoint_allowed("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_endpoint_allowed"("p_endpoint" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  SELECT coalesce(p_endpoint ~ '^https://(fcm\.googleapis\.com|[a-z0-9.-]+\.push\.services\.mozilla\.com|[a-z0-9.-]*push\.apple\.com|[a-z0-9.-]+\.notify\.windows\.com)/[^\s]+$', false)
$_$;


--
-- Name: push_event_category("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_event_category"("p_app" "text", "p_event" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN p_app = 'admin' THEN CASE
      WHEN p_event IN ('mail') THEN 'mail'
      WHEN p_event IN ('ticket') THEN 'ticket'
      WHEN p_event IN ('market') THEN 'market'
      WHEN p_event IN ('collect_done','collect_paused') THEN 'collect'
      WHEN p_event IN ('job_error','job_error_repeat') THEN 'errors'
      ELSE 'other' END
    ELSE CASE
      WHEN p_event LIKE 'friend:%' THEN 'friend'
      WHEN p_event LIKE 'poll:%' THEN 'poll'
      WHEN p_event LIKE 'subscription:%' THEN 'subscription'
      WHEN p_event LIKE 'base:%' THEN 'base'
      WHEN p_event LIKE 'device:%' THEN 'device'
      WHEN p_event LIKE 'copy:%' THEN 'copy'
      ELSE 'other' END
  END
$$;


--
-- Name: push_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."push_outbox" (
    "id" bigint NOT NULL,
    "app" "text" NOT NULL,
    "user_id" "uuid",
    "event" "text" NOT NULL,
    "category" "text" NOT NULL,
    "vars" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "ttl" integer DEFAULT 86400 NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "attempts" integer DEFAULT 0 NOT NULL,
    "sent_at" timestamp with time zone,
    "delivered" integer DEFAULT 0 NOT NULL,
    "failed" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    CONSTRAINT "push_outbox_app_check" CHECK (("app" = ANY (ARRAY['main'::"text", 'admin'::"text"]))),
    CONSTRAINT "push_outbox_category_check" CHECK (("category" ~ '^[a-z_]{2,30}$'::"text")),
    CONSTRAINT "push_outbox_event_check" CHECK (("event" ~ '^[a-z_:]{2,40}$'::"text")),
    CONSTRAINT "push_outbox_last_error_check" CHECK (("char_length"("last_error") <= 200)),
    CONSTRAINT "push_outbox_owner" CHECK ((("app" = 'main'::"text") = ("user_id" IS NOT NULL))),
    CONSTRAINT "push_outbox_ttl_check" CHECK ((("ttl" >= 60) AND ("ttl" <= 604800))),
    CONSTRAINT "push_outbox_urgency_check" CHECK (("urgency" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text"]))),
    CONSTRAINT "push_outbox_vars_check" CHECK (("pg_column_size"("vars") <= 2000))
);


--
-- Name: push_outbox_claim(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_outbox_claim"("p_limit" integer DEFAULT 50) RETURNS SETOF "public"."push_outbox"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  UPDATE public.push_outbox o SET claimed_at = now(), attempts = o.attempts + 1
   WHERE o.id IN (
     SELECT id FROM public.push_outbox
      WHERE sent_at IS NULL AND attempts < 5 AND created_at > now() - interval '1 day'
        AND (claimed_at IS NULL OR claimed_at < now() - interval '2 minutes')
      ORDER BY id LIMIT greatest(1, least(coalesce(p_limit, 50), 200))
      FOR UPDATE SKIP LOCKED)
  RETURNING o.*
$$;


--
-- Name: push_outbox_finish(bigint, integer, integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_outbox_finish"("p_id" bigint, "p_delivered" integer, "p_failed" integer, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  UPDATE public.push_outbox SET sent_at = now(), delivered = greatest(0, coalesce(p_delivered, 0)),
    failed = greatest(0, coalesce(p_failed, 0)), last_error = left(p_error, 200)
   WHERE id = p_id
$$;


--
-- Name: push_outbox_maintain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_outbox_maintain"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM public.push_outbox WHERE created_at < now() - interval '14 days';
  IF EXISTS (SELECT 1 FROM public.push_outbox WHERE sent_at IS NULL AND attempts < 5
               AND created_at > now() - interval '1 day' AND created_at < now() - interval '1 minute') THEN
    PERFORM public.push_send_kick();
  END IF;
END $$;


--
-- Name: push_outbox_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_outbox_stats"("p_hours" integer DEFAULT 24) RETURNS TABLE("app" "text", "event" "text", "events" bigint, "waiting" bigint, "delivered" bigint, "failed" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT o.app, o.event, count(*), count(*) FILTER (WHERE o.sent_at IS NULL),
         coalesce(sum(o.delivered), 0), coalesce(sum(o.failed), 0)
    FROM public.push_outbox o
   WHERE o.created_at > now() - make_interval(hours => greatest(1, least(coalesce(p_hours, 24), 336)))
   GROUP BY o.app, o.event ORDER BY o.app, o.event
$$;


--
-- Name: push_send_kick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_send_kick"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_base text; v_anon text; v_secret text;
BEGIN
  SELECT decrypted_secret INTO v_base FROM vault.decrypted_secrets WHERE name = 'project_url';
  SELECT decrypted_secret INTO v_anon FROM vault.decrypted_secrets WHERE name = 'anon_key';
  SELECT btrim(decrypted_secret) INTO v_secret FROM vault.decrypted_secrets WHERE name = 'push_send_secret';
  IF coalesce(v_base,'') = '' OR coalesce(v_anon,'') = '' OR coalesce(v_secret,'') = '' THEN
    RAISE WARNING 'push_send_kick: brak project_url/anon_key/push_send_secret w vault';
    RETURN;
  END IF;
  PERFORM net.http_post(
    url := v_base || '/functions/v1/push-send',
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'Authorization','Bearer ' || v_anon,
      'apikey', v_anon,
      'X-Internal-Secret', encode(extensions.hmac('push-send', v_secret, 'sha256'), 'hex')),
    body := '{}'::jsonb);
EXCEPTION WHEN others THEN
  -- brak pg_net/vault nie może zablokować zdarzenia źródłowego; cron ponowi
  RAISE WARNING 'push_send_kick: %', sqlerrm;
END $$;


--
-- Name: push_subscribe("text", "text", "text", "text", "text"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_subscribe"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_lang" "text" DEFAULT 'pl'::"text", "p_kinds" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_rows integer;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF;
  IF coalesce((SELECT is_guest FROM public.profiles WHERE id = v_uid), false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'guest_forbidden');
  END IF;
  IF NOT public.push_endpoint_allowed(p_endpoint) THEN RETURN jsonb_build_object('ok', false, 'error', 'endpoint_not_allowed'); END IF;
  IF p_kinds IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(p_kinds) k WHERE k NOT IN ('friend','poll','subscription','base','device','copy')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_kinds');
  END IF;
  INSERT INTO public.push_subscriptions AS s (app, user_id, endpoint, p256dh, auth, lang, kinds, updated_at)
  VALUES ('main', v_uid, p_endpoint, p_p256dh, p_auth, coalesce(nullif(p_lang, ''), 'pl'), coalesce(p_kinds, '{}'), clock_timestamp())
  ON CONFLICT (endpoint) DO UPDATE SET p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth,
    lang = EXCLUDED.lang, kinds = EXCLUDED.kinds, updated_at = clock_timestamp(), fail_count = 0
    WHERE s.app = 'main' AND s.user_id = v_uid;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'endpoint_taken'); END IF;
  DELETE FROM public.push_subscriptions WHERE id IN (
    SELECT id FROM public.push_subscriptions WHERE app = 'main' AND user_id = v_uid
    ORDER BY updated_at DESC OFFSET 20);
  RETURN jsonb_build_object('ok', true);
END $$;


--
-- Name: push_subscription_get("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_subscription_get"("p_endpoint" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(
    (SELECT jsonb_build_object('subscribed', true, 'kinds', to_jsonb(kinds))
       FROM public.push_subscriptions WHERE endpoint = p_endpoint AND app = 'main' AND user_id = auth.uid()),
    jsonb_build_object('subscribed', false, 'kinds', '[]'::jsonb))
$$;


--
-- Name: push_subscription_result("uuid", boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_subscription_result"("p_id" "uuid", "p_ok" boolean, "p_gone" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_gone THEN DELETE FROM public.push_subscriptions WHERE id = p_id; RETURN; END IF;
  IF p_ok THEN
    UPDATE public.push_subscriptions SET last_ok_at = now(), fail_count = 0 WHERE id = p_id;
  ELSE
    UPDATE public.push_subscriptions SET fail_count = fail_count + 1 WHERE id = p_id;
    DELETE FROM public.push_subscriptions WHERE id = p_id AND fail_count >= 5;
  END IF;
END $$;


--
-- Name: push_unsubscribe("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_unsubscribe"("p_endpoint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF;
  DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND app = 'main' AND user_id = auth.uid();
  RETURN jsonb_build_object('ok', true);
END $$;


--
-- Name: push_user_event("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."push_user_event"("p_user" "uuid", "p_event" "text", "p_vars" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id bigint;
BEGIN
  IF p_user IS NULL OR NOT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE app = 'main' AND user_id = p_user) THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.push_outbox WHERE app = 'main' AND user_id = p_user AND event = p_event
               AND vars->>'id' IS NOT DISTINCT FROM p_vars->>'id' AND created_at > now() - interval '10 minutes') THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.push_outbox (app, user_id, event, category, vars)
  VALUES ('main', p_user, p_event, public.push_event_category('main', p_event), coalesce(p_vars, '{}'))
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: qb_apply_tag_states("uuid", "uuid"[], "uuid"[], "uuid"[], "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_apply_tag_states"("p_base_id" "uuid", "p_question_ids" "uuid"[], "p_folder_ids" "uuid"[], "p_on" "uuid"[], "p_off" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_added jsonb := '[]';
  v_removed jsonb := '[]';
BEGIN
  IF cardinality(coalesce(p_on, '{}')) > 0 THEN
    v_added := public.qb_set_tag_links(p_base_id, p_on, p_question_ids, p_folder_ids, true)->'questionLinks';
  END IF;
  IF cardinality(coalesce(p_off, '{}')) > 0 THEN
    -- okno tagów dotyczy pytań: bez bezpośrednich przypisań folderów
    v_removed := public.qb_set_tag_links(p_base_id, p_off,
      (SELECT coalesce(array_agg(id), '{}') FROM public.qb_questions
        WHERE base_id = p_base_id AND (id = ANY(coalesce(p_question_ids, '{}'))
          OR category_id IN (SELECT id FROM public._qb_folder_subtree(p_base_id, p_folder_ids)))),
      NULL, false)->'questionLinks';
  END IF;
  RETURN jsonb_build_object('added', v_added, 'removed', v_removed);
END;
$$;


--
-- Name: qb_base_content("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_base_content"("p_base_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.base_can_access(p_base_id, auth.uid()) THEN
    RETURN '{"categories":[],"tags":[],"questions":[],"questionTags":[]}'::jsonb;
  END IF;
  RETURN jsonb_build_object(
    'categories', coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', c.id, 'base_id', c.base_id, 'parent_id', c.parent_id, 'name', c.name,
                                          'ord', c.ord, 'created_at', c.created_at, 'updated_at', c.updated_at)
                       ORDER BY c.ord, c.id)
        FROM public.qb_categories c WHERE c.base_id = p_base_id), '[]'::jsonb),
    'tags', coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', t.id, 'base_id', t.base_id, 'name', t.name, 'color', t.color, 'ord', t.ord)
                       ORDER BY t.ord, t.id)
        FROM public.qb_tags t WHERE t.base_id = p_base_id), '[]'::jsonb),
    'questions', coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', q.id, 'base_id', q.base_id, 'category_id', q.category_id, 'ord', q.ord,
                                          'payload', q.payload, 'created_at', q.created_at, 'updated_at', q.updated_at)
                       ORDER BY q.ord, q.id)
        FROM public.qb_questions q WHERE q.base_id = p_base_id), '[]'::jsonb),
    'questionTags', coalesce((
      SELECT jsonb_agg(jsonb_build_object('question_id', l.question_id, 'tag_id', l.tag_id))
        FROM public.qb_question_tags l
        JOIN public.qb_questions q ON q.id = l.question_id
       WHERE q.base_id = p_base_id), '[]'::jsonb)
  );
END;
$$;


--
-- Name: qb_copy_items("uuid", "uuid"[], "uuid"[], "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_copy_items"("p_base_id" "uuid", "p_question_ids" "uuid"[], "p_folder_ids" "uuid"[], "p_target" "uuid", "p_copy_label" "text" DEFAULT 'kopia'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_src uuid;
  v_fmap jsonb;   -- {stary_id_folderu: nowy_id}
  v_qmap jsonb;   -- [{old, new, cat, ord}]
  v_ord int;
  v_new_q jsonb := '[]';
  v_new_f jsonb := '[]';
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_items(p_base_id, p_question_ids, p_folder_ids);
  PERFORM public._qb_assert_folder(p_base_id, p_target);

  -- 1) foldery: każdy jako osobne drzewo w miejscu docelowym; nowe id
  -- z góry, więc całe poddrzewo wstawia jedno polecenie
  FOREACH v_src IN ARRAY coalesce(p_folder_ids, '{}') LOOP
    SELECT jsonb_object_agg(s.id::text, gen_random_uuid()) INTO v_fmap
      FROM public._qb_folder_subtree(p_base_id, ARRAY[v_src]) s;

    INSERT INTO public.qb_categories (id, base_id, parent_id, name, ord)
    SELECT (v_fmap->>c.id::text)::uuid, p_base_id,
      CASE WHEN c.id = v_src THEN p_target ELSE (v_fmap->>c.parent_id::text)::uuid END,
      CASE WHEN c.id = v_src THEN public._qb_unique_folder_name(p_base_id, p_target, c.name, p_copy_label)
           ELSE left(coalesce(c.name, 'Folder'), 80) END,
      CASE WHEN c.id = v_src THEN (SELECT coalesce(max(x.ord), 0) + 1 FROM public.qb_categories x
                                    WHERE x.base_id = p_base_id AND x.parent_id IS NOT DISTINCT FROM p_target)
           ELSE c.ord END
      FROM public.qb_categories c
     WHERE c.base_id = p_base_id AND v_fmap ? c.id::text;

    SELECT coalesce(jsonb_agg(jsonb_build_object('old', q.id, 'new', gen_random_uuid(),
             'cat', v_fmap->>q.category_id::text, 'ord', q.ord)), '[]')
      INTO v_qmap
      FROM public.qb_questions q
     WHERE q.base_id = p_base_id AND v_fmap ? q.category_id::text;
    PERFORM public._qb_insert_question_copies(p_base_id, v_qmap);

    v_new_f := v_new_f || to_jsonb(v_fmap->>v_src::text);
  END LOOP;

  -- 2) pytania: kolejność tablicy, na koniec folderu docelowego
  SELECT coalesce(max(ord), 0) INTO v_ord FROM public.qb_questions
   WHERE base_id = p_base_id AND category_id IS NOT DISTINCT FROM p_target;
  SELECT coalesce(jsonb_agg(jsonb_build_object('old', x.id, 'new', gen_random_uuid(),
           'cat', p_target, 'ord', v_ord + x.n) ORDER BY x.n), '[]')
    INTO v_qmap
    FROM unnest(coalesce(p_question_ids, '{}')) WITH ORDINALITY x(id, n);
  PERFORM public._qb_insert_question_copies(p_base_id, v_qmap);
  SELECT coalesce(jsonb_agg(m->'new' ORDER BY (m->>'ord')::int), '[]') INTO v_new_q
    FROM jsonb_array_elements(v_qmap) m;

  RETURN jsonb_build_object('questions', v_new_q, 'folders', v_new_f);
END;
$$;


--
-- Name: qb_create_folder("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_create_folder"("p_base_id" "uuid", "p_parent_id" "uuid", "p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name text := left(btrim(coalesce(p_name, '')), 80);
  v_id uuid;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_folder(p_base_id, p_parent_id);
  IF v_name = '' THEN RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001'; END IF;

  INSERT INTO public.qb_categories (base_id, parent_id, name, ord)
  VALUES (p_base_id, p_parent_id, v_name,
    (SELECT coalesce(max(ord), 0) + 1 FROM public.qb_categories
      WHERE base_id = p_base_id AND parent_id IS NOT DISTINCT FROM p_parent_id))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: qb_create_question("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_create_question"("p_base_id" "uuid", "p_category_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_folder(p_base_id, p_category_id);
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001';
  END IF;

  INSERT INTO public.qb_questions (base_id, category_id, ord, payload, updated_by)
  VALUES (p_base_id, p_category_id,
    (SELECT coalesce(max(ord), 0) + 1 FROM public.qb_questions
      WHERE base_id = p_base_id AND category_id IS NOT DISTINCT FROM p_category_id),
    p_payload, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: qb_delete_items("uuid", "uuid"[], "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_delete_items"("p_base_id" "uuid", "p_question_ids" "uuid"[], "p_folder_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_all_folders uuid[];
  v_top_folders uuid[];
  v_sub uuid[];
  v_trash uuid[] := '{}';
  v_tid uuid;
  v_q int := 0;
  v_c int := 0;
  r record;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_items(p_base_id, p_question_ids, p_folder_ids);

  SELECT coalesce(array_agg(id), '{}') INTO v_all_folders FROM public._qb_folder_subtree(p_base_id, p_folder_ids);
  -- foldery najwyższego poziomu: rodzic nie jest w poddrzewie innego zaznaczonego
  SELECT coalesce(array_agg(c.id), '{}') INTO v_top_folders
    FROM public.qb_categories c
   WHERE c.base_id = p_base_id AND c.id = ANY(coalesce(p_folder_ids, '{}'))
     AND (c.parent_id IS NULL OR NOT c.parent_id = ANY(v_all_folders));

  FOR r IN SELECT c.* FROM public.qb_categories c WHERE c.id = ANY(v_top_folders) ORDER BY c.ord LOOP
    SELECT coalesce(array_agg(id), '{}') INTO v_sub FROM public._qb_folder_subtree(p_base_id, ARRAY[r.id]);
    INSERT INTO public.qb_trash (base_id, kind, label, origin_id, item_id, n_questions, n_folders, snapshot, deleted_by)
    SELECT p_base_id, 'folder', r.name, r.parent_id, r.id,
      (SELECT count(*) FROM public.qb_questions WHERE base_id = p_base_id AND category_id = ANY(v_sub)),
      cardinality(v_sub),
      jsonb_build_object(
        'folders', (SELECT jsonb_agg(to_jsonb(c)) FROM public.qb_categories c WHERE c.id = ANY(v_sub)),
        'questions', coalesce((SELECT jsonb_agg(to_jsonb(q)) FROM public.qb_questions q
                                WHERE q.base_id = p_base_id AND q.category_id = ANY(v_sub)), '[]'),
        'questionTags', coalesce((SELECT jsonb_agg(jsonb_build_object('question_id', l.question_id, 'tag_id', l.tag_id))
                                   FROM public.qb_question_tags l JOIN public.qb_questions q ON q.id = l.question_id
                                  WHERE q.base_id = p_base_id AND q.category_id = ANY(v_sub)), '[]')),
      auth.uid()
    RETURNING id INTO v_tid;
    v_trash := v_trash || v_tid;
  END LOOP;

  FOR r IN SELECT q.* FROM public.qb_questions q
            WHERE q.base_id = p_base_id AND q.id = ANY(coalesce(p_question_ids, '{}'))
              AND (q.category_id IS NULL OR NOT q.category_id = ANY(v_all_folders))
            ORDER BY q.ord LOOP
    INSERT INTO public.qb_trash (base_id, kind, label, origin_id, item_id, n_questions, n_folders, snapshot, deleted_by)
    VALUES (p_base_id, 'question', coalesce(r.payload->>'text', ''), r.category_id, r.id, 1, 0,
      jsonb_build_object(
        'folders', '[]'::jsonb,
        'questions', jsonb_build_array(to_jsonb(r)),
        'questionTags', coalesce((SELECT jsonb_agg(jsonb_build_object('question_id', l.question_id, 'tag_id', l.tag_id))
                                   FROM public.qb_question_tags l WHERE l.question_id = r.id), '[]')),
      auth.uid())
    RETURNING id INTO v_tid;
    v_trash := v_trash || v_tid;
  END LOOP;

  DELETE FROM public.qb_questions
   WHERE base_id = p_base_id
     AND (id = ANY(coalesce(p_question_ids, '{}')) OR category_id = ANY(v_all_folders));
  GET DIAGNOSTICS v_q = ROW_COUNT;
  DELETE FROM public.qb_categories WHERE base_id = p_base_id AND id = ANY(v_all_folders);
  GET DIAGNOSTICS v_c = ROW_COUNT;

  RETURN jsonb_build_object('questions', v_q, 'folders', v_c, 'trash', to_jsonb(v_trash));
END;
$$;


--
-- Name: qb_delete_tags("uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_delete_tags"("p_base_id" "uuid", "p_tag_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_before jsonb;
  v_ids uuid[];
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  SELECT coalesce(array_agg(id), '{}') INTO v_ids FROM public.qb_tags
   WHERE base_id = p_base_id AND id = ANY(coalesce(p_tag_ids, '{}'));
  IF cardinality(v_ids) <> (SELECT count(DISTINCT x) FROM unnest(coalesce(p_tag_ids, '{}')) x) THEN
    RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001';
  END IF;

  SELECT jsonb_build_object(
    'tags', coalesce((SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name, 'color', color, 'ord', ord))
       FROM public.qb_tags WHERE id = ANY(v_ids)), '[]'),
    'questionLinks', coalesce((SELECT jsonb_agg(jsonb_build_object('question_id', question_id, 'tag_id', tag_id))
       FROM public.qb_question_tags WHERE tag_id = ANY(v_ids)), '[]'),
    'folderLinks', coalesce((SELECT jsonb_agg(jsonb_build_object('category_id', category_id, 'tag_id', tag_id))
       FROM public.qb_category_tags WHERE tag_id = ANY(v_ids)), '[]')
  ) INTO v_before;

  DELETE FROM public.qb_tags WHERE id = ANY(v_ids); -- przypisania: ON DELETE CASCADE
  RETURN v_before;
END;
$$;


--
-- Name: qb_move_items("uuid", "uuid"[], "uuid"[], "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_move_items"("p_base_id" "uuid", "p_question_ids" "uuid"[], "p_folder_ids" "uuid"[], "p_target" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_before jsonb;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_items(p_base_id, p_question_ids, p_folder_ids);
  PERFORM public._qb_assert_folder(p_base_id, p_target);
  PERFORM public._qb_assert_no_cycle(p_base_id, p_folder_ids, p_target);

  SELECT jsonb_build_object(
    'questions', coalesce((SELECT jsonb_agg(jsonb_build_object('id', id, 'category_id', category_id, 'ord', ord))
       FROM public.qb_questions WHERE base_id = p_base_id AND id = ANY(coalesce(p_question_ids, '{}'))), '[]'),
    'folders', coalesce((SELECT jsonb_agg(jsonb_build_object('id', id, 'parent_id', parent_id, 'ord', ord))
       FROM public.qb_categories WHERE base_id = p_base_id AND id = ANY(coalesce(p_folder_ids, '{}'))), '[]')
  ) INTO v_before;

  UPDATE public.qb_questions SET category_id = p_target, updated_by = auth.uid()
   WHERE base_id = p_base_id AND id = ANY(coalesce(p_question_ids, '{}'));
  UPDATE public.qb_categories SET parent_id = p_target
   WHERE base_id = p_base_id AND id = ANY(coalesce(p_folder_ids, '{}'));

  RETURN v_before;
END;
$$;


--
-- Name: qb_question_tag_links("uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_question_tag_links"("p_base_id" "uuid", "p_question_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.base_can_access(p_base_id, auth.uid()) THEN RETURN '[]'::jsonb; END IF;
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object('question_id', l.question_id, 'tag_id', l.tag_id))
      FROM public.qb_question_tags l
      JOIN public.qb_questions q ON q.id = l.question_id
     WHERE q.base_id = p_base_id AND l.question_id = ANY(coalesce(p_question_ids, '{}'))), '[]'::jsonb);
END;
$$;


--
-- Name: qb_rename_folder("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_rename_folder"("p_base_id" "uuid", "p_id" "uuid", "p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name text := left(btrim(coalesce(p_name, '')), 80);
  v_old text;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  IF v_name = '' THEN RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001'; END IF;
  SELECT name INTO v_old FROM public.qb_categories WHERE id = p_id AND base_id = p_base_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001'; END IF;
  UPDATE public.qb_categories SET name = v_name WHERE id = p_id;
  RETURN v_old;
END;
$$;


--
-- Name: qb_reorder_folders("uuid", "uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_reorder_folders"("p_base_id" "uuid", "p_parent_id" "uuid", "p_ordered_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_before jsonb;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_items(p_base_id, NULL, p_ordered_ids);
  PERFORM public._qb_assert_folder(p_base_id, p_parent_id);
  PERFORM public._qb_assert_no_cycle(p_base_id, p_ordered_ids, p_parent_id);

  SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'parent_id', parent_id, 'ord', ord)), '[]')
    INTO v_before
    FROM public.qb_categories WHERE base_id = p_base_id AND id = ANY(p_ordered_ids);

  UPDATE public.qb_categories c SET parent_id = p_parent_id, ord = x.n
    FROM unnest(p_ordered_ids) WITH ORDINALITY x(id, n)
   WHERE c.id = x.id AND c.base_id = p_base_id;

  RETURN jsonb_build_object('folders', v_before);
END;
$$;


--
-- Name: qb_restore_positions("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_restore_positions"("p_base_id" "uuid", "p_positions" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);

  UPDATE public.qb_categories c
     SET parent_id = CASE WHEN EXISTS (SELECT 1 FROM public.qb_categories p
                                        WHERE p.id = (x->>'parent_id')::uuid AND p.base_id = p_base_id)
                          THEN (x->>'parent_id')::uuid END,
         ord = coalesce((x->>'ord')::int, c.ord)
    FROM jsonb_array_elements(coalesce(p_positions->'folders', '[]')) x
   WHERE c.id = (x->>'id')::uuid AND c.base_id = p_base_id;

  UPDATE public.qb_questions q
     SET category_id = CASE WHEN EXISTS (SELECT 1 FROM public.qb_categories p
                                          WHERE p.id = (x->>'category_id')::uuid AND p.base_id = p_base_id)
                            THEN (x->>'category_id')::uuid END,
         ord = coalesce((x->>'ord')::int, q.ord),
         updated_by = auth.uid()
    FROM jsonb_array_elements(coalesce(p_positions->'questions', '[]')) x
   WHERE q.id = (x->>'id')::uuid AND q.base_id = p_base_id;

  -- przywrócone położenie nie może zrobić cyklu (ktoś mógł w międzyczasie
  -- przenieść rodzica do środka): taki folder ląduje w korzeniu
  UPDATE public.qb_categories c SET parent_id = NULL
   WHERE c.base_id = p_base_id
     AND c.id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(coalesce(p_positions->'folders', '[]')) x)
     AND c.parent_id IN (SELECT id FROM public._qb_folder_subtree(p_base_id, ARRAY[c.id]));
END;
$$;


--
-- Name: qb_restore_tag_links("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_restore_tag_links"("p_base_id" "uuid", "p_add" "jsonb", "p_remove" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);

  DELETE FROM public.qb_question_tags l
   USING jsonb_array_elements(coalesce(p_remove, '[]')) x
   WHERE l.question_id = (x->>'question_id')::uuid AND l.tag_id = (x->>'tag_id')::uuid
     AND EXISTS (SELECT 1 FROM public.qb_tags t WHERE t.id = l.tag_id AND t.base_id = p_base_id);

  INSERT INTO public.qb_question_tags (question_id, tag_id)
  SELECT DISTINCT (x->>'question_id')::uuid, (x->>'tag_id')::uuid
    FROM jsonb_array_elements(coalesce(p_add, '[]')) x
   WHERE EXISTS (SELECT 1 FROM public.qb_questions q WHERE q.id = (x->>'question_id')::uuid AND q.base_id = p_base_id)
     AND EXISTS (SELECT 1 FROM public.qb_tags t WHERE t.id = (x->>'tag_id')::uuid AND t.base_id = p_base_id)
  ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: qb_restore_tags("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_restore_tags"("p_base_id" "uuid", "p_snapshot" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(coalesce(p_snapshot->'tags', '[]')) x
      JOIN public.qb_tags t ON t.base_id = p_base_id AND public._qb_tag_key(t.name) = public._qb_tag_key(x->>'name') AND t.id <> (x->>'id')::uuid
  ) THEN
    RAISE EXCEPTION 'qb:duplicate' USING errcode = 'P0001';
  END IF;

  INSERT INTO public.qb_tags (id, base_id, name, color, ord)
  SELECT (x->>'id')::uuid, p_base_id, x->>'name', coalesce(x->>'color', '#4da3ff'), coalesce((x->>'ord')::int, 9999)
    FROM jsonb_array_elements(coalesce(p_snapshot->'tags', '[]')) x
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.qb_question_tags (question_id, tag_id)
  SELECT DISTINCT (x->>'question_id')::uuid, (x->>'tag_id')::uuid
    FROM jsonb_array_elements(coalesce(p_snapshot->'questionLinks', '[]')) x
   WHERE EXISTS (SELECT 1 FROM public.qb_questions q WHERE q.id = (x->>'question_id')::uuid AND q.base_id = p_base_id)
     AND EXISTS (SELECT 1 FROM public.qb_tags t WHERE t.id = (x->>'tag_id')::uuid AND t.base_id = p_base_id)
  ON CONFLICT DO NOTHING;

  INSERT INTO public.qb_category_tags (category_id, tag_id)
  SELECT DISTINCT (x->>'category_id')::uuid, (x->>'tag_id')::uuid
    FROM jsonb_array_elements(coalesce(p_snapshot->'folderLinks', '[]')) x
   WHERE EXISTS (SELECT 1 FROM public.qb_categories c WHERE c.id = (x->>'category_id')::uuid AND c.base_id = p_base_id)
     AND EXISTS (SELECT 1 FROM public.qb_tags t WHERE t.id = (x->>'tag_id')::uuid AND t.base_id = p_base_id)
     -- qb_category_tags nie ma klucza głównego: bez duplikatów ręcznie
     AND NOT EXISTS (SELECT 1 FROM public.qb_category_tags l
                      WHERE l.category_id = (x->>'category_id')::uuid AND l.tag_id = (x->>'tag_id')::uuid);
END;
$$;


--
-- Name: qb_save_question("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_save_question"("p_base_id" "uuid", "p_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old jsonb;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001';
  END IF;
  SELECT payload INTO v_old FROM public.qb_questions WHERE id = p_id AND base_id = p_base_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001'; END IF;
  UPDATE public.qb_questions SET payload = p_payload, updated_by = auth.uid() WHERE id = p_id;
  RETURN v_old;
END;
$$;


--
-- Name: qb_save_tag("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_save_tag"("p_base_id" "uuid", "p_id" "uuid", "p_name" "text", "p_color" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_name text := left(regexp_replace(btrim(coalesce(p_name, '')), '^#', ''), 40);
  v_color text := coalesce(nullif(btrim(p_color), ''), '#4da3ff');
  v_before jsonb;
  v_id uuid;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  -- litery (także polskie, decyzja 2026-10-20), cyfry i _
  IF v_name !~ '^[a-zA-Z0-9_ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]+$' THEN RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001'; END IF;
  IF EXISTS (SELECT 1 FROM public.qb_tags WHERE base_id = p_base_id AND public._qb_tag_key(name) = public._qb_tag_key(v_name)
              AND id IS DISTINCT FROM p_id) THEN
    RAISE EXCEPTION 'qb:duplicate' USING errcode = 'P0001';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.qb_tags (base_id, name, color, ord) VALUES (p_base_id, v_name, v_color, 9999)
    RETURNING id INTO v_id;
    RETURN jsonb_build_object('id', v_id, 'before', NULL);
  END IF;

  SELECT jsonb_build_object('name', name, 'color', color) INTO v_before
    FROM public.qb_tags WHERE id = p_id AND base_id = p_base_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001'; END IF;
  UPDATE public.qb_tags SET name = v_name, color = v_color WHERE id = p_id;
  RETURN jsonb_build_object('id', p_id, 'before', v_before);
END;
$_$;


--
-- Name: qb_set_question_text("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_set_question_text"("p_base_id" "uuid", "p_id" "uuid", "p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_text text := btrim(coalesce(p_text, ''));
  v_old text;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  IF v_text = '' THEN RAISE EXCEPTION 'qb:invalid' USING errcode = 'P0001'; END IF;
  SELECT coalesce(payload->>'text', '') INTO v_old FROM public.qb_questions
    WHERE id = p_id AND base_id = p_base_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001'; END IF;
  UPDATE public.qb_questions
     SET payload = jsonb_set(CASE WHEN jsonb_typeof(payload) = 'object' THEN payload ELSE '{}'::jsonb END,
                             '{text}', to_jsonb(v_text)),
         updated_by = auth.uid()
   WHERE id = p_id;
  RETURN v_old;
END;
$$;


--
-- Name: qb_set_tag_links("uuid", "uuid"[], "uuid"[], "uuid"[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_set_tag_links"("p_base_id" "uuid", "p_tag_ids" "uuid"[], "p_question_ids" "uuid"[], "p_folder_ids" "uuid"[], "p_on" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_q uuid[];
  v_folders uuid[];
  v_qlinks jsonb;
  v_flinks jsonb := '[]';
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  PERFORM public._qb_assert_items(p_base_id, p_question_ids, p_folder_ids);
  IF (SELECT count(DISTINCT x) FROM unnest(coalesce(p_tag_ids, '{}')) x)
     <> (SELECT count(*) FROM public.qb_tags WHERE base_id = p_base_id AND id = ANY(coalesce(p_tag_ids, '{}'))) THEN
    RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001';
  END IF;

  SELECT coalesce(array_agg(id), '{}') INTO v_folders FROM public._qb_folder_subtree(p_base_id, p_folder_ids);
  SELECT coalesce(array_agg(DISTINCT id), '{}') INTO v_q FROM public.qb_questions
   WHERE base_id = p_base_id AND (id = ANY(coalesce(p_question_ids, '{}')) OR category_id = ANY(v_folders));

  IF p_on THEN
    WITH ins AS (
      INSERT INTO public.qb_question_tags (question_id, tag_id)
      SELECT q, t FROM unnest(v_q) q CROSS JOIN unnest(p_tag_ids) t
      WHERE NOT EXISTS (SELECT 1 FROM public.qb_question_tags l WHERE l.question_id = q AND l.tag_id = t)
      RETURNING question_id, tag_id
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('question_id', question_id, 'tag_id', tag_id)), '[]') INTO v_qlinks FROM ins;
  ELSE
    WITH del AS (
      DELETE FROM public.qb_question_tags WHERE question_id = ANY(v_q) AND tag_id = ANY(p_tag_ids)
      RETURNING question_id, tag_id
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('question_id', question_id, 'tag_id', tag_id)), '[]') INTO v_qlinks FROM del;
    WITH del AS (
      DELETE FROM public.qb_category_tags WHERE category_id = ANY(coalesce(p_folder_ids, '{}')) AND tag_id = ANY(p_tag_ids)
      RETURNING category_id, tag_id
    )
    SELECT coalesce(jsonb_agg(jsonb_build_object('category_id', category_id, 'tag_id', tag_id)), '[]') INTO v_flinks FROM del;
  END IF;

  RETURN jsonb_build_object('questionLinks', v_qlinks, 'folderLinks', v_flinks);
END;
$$;


--
-- Name: qb_trash_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_trash_cleanup"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_n int;
BEGIN
  DELETE FROM public.qb_trash WHERE deleted_at < now() - interval '30 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: qb_trash_list("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_trash_list"("p_base_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
      'id', t.id, 'kind', t.kind, 'label', t.label, 'item_id', t.item_id, 'origin_id', t.origin_id,
      'n_questions', t.n_questions, 'n_folders', t.n_folders,
      'deleted_at', t.deleted_at, 'expires_at', t.deleted_at + interval '30 days')
      ORDER BY t.deleted_at DESC, t.id)
    FROM public.qb_trash t WHERE t.base_id = p_base_id), '[]');
END;
$$;


--
-- Name: qb_trash_purge("uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_trash_purge"("p_base_id" "uuid", "p_trash_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_n int;
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  DELETE FROM public.qb_trash
   WHERE base_id = p_base_id AND (p_trash_ids IS NULL OR id = ANY(p_trash_ids));
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;


--
-- Name: qb_trash_restore("uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qb_trash_restore"("p_base_id" "uuid", "p_trash_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
  v_parent uuid;
  v_q jsonb := '[]';
  v_f jsonb := '[]';
BEGIN
  PERFORM public._qb_assert_edit(p_base_id);
  IF (SELECT count(DISTINCT x) FROM unnest(coalesce(p_trash_ids, '{}')) x)
     <> (SELECT count(*) FROM public.qb_trash WHERE base_id = p_base_id AND id = ANY(coalesce(p_trash_ids, '{}'))) THEN
    RAISE EXCEPTION 'qb:gone' USING errcode = 'P0001';
  END IF;

  FOR r IN SELECT * FROM public.qb_trash
            WHERE base_id = p_base_id AND id = ANY(p_trash_ids)
            ORDER BY deleted_at, id
            FOR UPDATE LOOP
    -- miejsce: dawny folder, jeśli nadal jest w bazie, inaczej korzeń
    SELECT id INTO v_parent FROM public.qb_categories WHERE id = r.origin_id AND base_id = p_base_id;

    INSERT INTO public.qb_categories (id, base_id, parent_id, name, ord, created_at, updated_at)
    SELECT f.id, p_base_id,
           CASE WHEN f.id = r.item_id THEN v_parent ELSE f.parent_id END,
           f.name, f.ord, f.created_at, f.updated_at
      FROM jsonb_populate_recordset(NULL::public.qb_categories, r.snapshot->'folders') f
    ON CONFLICT (id) DO NOTHING;

    INSERT INTO public.qb_questions (id, base_id, category_id, ord, payload, created_at, updated_at, updated_by)
    SELECT q.id, p_base_id,
           CASE WHEN r.kind = 'question' THEN v_parent ELSE q.category_id END,
           q.ord, q.payload, q.created_at, q.updated_at, q.updated_by
      FROM jsonb_populate_recordset(NULL::public.qb_questions, r.snapshot->'questions') q
    ON CONFLICT (id) DO NOTHING;

    INSERT INTO public.qb_question_tags (question_id, tag_id)
    SELECT (l->>'question_id')::uuid, (l->>'tag_id')::uuid
      FROM jsonb_array_elements(coalesce(r.snapshot->'questionTags', '[]')) l
     WHERE EXISTS (SELECT 1 FROM public.qb_tags t WHERE t.id = (l->>'tag_id')::uuid AND t.base_id = p_base_id)
       AND EXISTS (SELECT 1 FROM public.qb_questions q WHERE q.id = (l->>'question_id')::uuid AND q.base_id = p_base_id)
    ON CONFLICT DO NOTHING;

    IF r.kind = 'folder' THEN v_f := v_f || to_jsonb(r.item_id); ELSE v_q := v_q || to_jsonb(r.item_id); END IF;
    DELETE FROM public.qb_trash WHERE id = r.id;
  END LOOP;

  RETURN jsonb_build_object('questions', v_q, 'folders', v_f);
END;
$$;


--
-- Name: qf_ai_reserve("uuid", "text", integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_ai_reserve"("p_id" "uuid", "p_service" "text", "p_tokens" integer, "p_limit" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE used bigint;
BEGIN
 IF p_service NOT IN ('marketing','questions') OR p_tokens<1 OR p_limit<1 THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qf-ai:'||p_service,0));
 IF EXISTS(SELECT 1 FROM producer_ai_usage WHERE request_id=p_id) THEN RETURN true; END IF;
 SELECT coalesce(sum(coalesce(actual,reserved)),0) INTO used FROM producer_ai_usage WHERE service=p_service AND day=(now() AT TIME ZONE 'UTC')::date;
 IF used+p_tokens>p_limit THEN RETURN false; END IF;
 INSERT INTO producer_ai_usage(request_id,service,reserved) VALUES(p_id,p_service,p_tokens);
 RETURN true;
END $$;


--
-- Name: qf_candidates("text", "jsonb", boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_candidates"("p_lang" "text", "p_embedding" "jsonb" DEFAULT NULL::"jsonb", "p_include_ai" boolean DEFAULT false, "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(q)-'embedding'-'fingerprint'-'answer_key'), '[]'::jsonb) FROM (
  SELECT * FROM producer_question_pool WHERE lang=p_lang AND (p_include_ai OR origin='search')
   AND (p_embedding IS NULL OR 1-(embedding<=>(p_embedding::text::public.vector(384)))>=0.18)
  ORDER BY CASE WHEN p_embedding IS NULL THEN 0 ELSE embedding<=>(p_embedding::text::public.vector(384)) END,created_at,id
  LIMIT greatest(1,least(p_limit,10000))
 ) q
$$;


--
-- Name: qf_delete("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_delete"("p_id" "uuid", "p_lang" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g producer_question_games; m market_games; target uuid; kept integer:=0;
BEGIN
 IF p_lang NOT IN ('pl','en','uk') THEN RAISE EXCEPTION 'invalid_language'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qf:'||p_lang,0));
 SELECT * INTO g FROM producer_question_games WHERE id=p_id AND lang=p_lang FOR UPDATE;
 IF FOUND THEN target:=g.published_id;
 ELSE
  SELECT id INTO target FROM market_games WHERE id=p_id AND lang=p_lang AND origin='producer';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
 END IF;
 IF target IS NOT NULL THEN
  SELECT * INTO m FROM market_games WHERE id=target FOR UPDATE;
  IF FOUND THEN
   IF m.status='published' THEN RETURN jsonb_build_object('ok',false,'reason','published'); END IF;
   -- Ślad pytań zostaje (bez pełnej kopii gry): blokuje ponowne znalezienie tej samej treści.
   INSERT INTO producer_question_history(lang,fingerprint,question_norm,answer_key,embedding,game_id)
   SELECT m.lang,encode(sha256(convert_to(q.question_norm,'UTF8')),'hex'),q.question_norm,
    encode(sha256(convert_to(coalesce((SELECT jsonb_agg(x ORDER BY x) FROM unnest(q.answer_keys) x),'[]'::jsonb)::text,'UTF8')),'hex'),
    q.embedding,m.id
   FROM market_game_questions q WHERE q.game_id=m.id AND q.embedding IS NOT NULL AND length(q.question_norm)>0
   ON CONFLICT(lang,fingerprint) DO NOTHING;
   GET DIAGNOSTICS kept=ROW_COUNT;
   DELETE FROM market_games WHERE id=m.id;
  END IF;
 END IF;
 IF g.id IS NOT NULL THEN DELETE FROM producer_question_games WHERE id=g.id; END IF;
 RETURN jsonb_build_object('ok',true,'history_added',kept);
END $$;


--
-- Name: qf_disassemble("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_disassemble"("p_id" "uuid", "p_lang" "text", "p_questions" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g producer_question_games; m market_games; target uuid; g_title text; q jsonb; a jsonb; norm text; fp text; ak text; av public.vector(384);
 n integer; restored integer:=0; skipped integer:=0; duplicates integer:=0; bad boolean; q_origin text; src jsonb;
BEGIN
 IF p_lang NOT IN ('pl','en','uk') OR jsonb_typeof(p_questions) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_request'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qf:'||p_lang,0));
 SELECT * INTO g FROM producer_question_games WHERE id=p_id AND lang=p_lang FOR UPDATE;
 IF FOUND THEN target:=g.published_id; g_title:=g.title;
 ELSE
  SELECT mg.id,mg.title INTO target,g_title FROM market_games mg WHERE mg.id=p_id AND mg.lang=p_lang AND mg.origin='producer';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','not_found'); END IF;
 END IF;
 IF target IS NOT NULL THEN
  SELECT * INTO m FROM market_games WHERE id=target FOR UPDATE;
  IF FOUND AND m.status='published' THEN RETURN jsonb_build_object('ok',false,'reason','published'); END IF;
 END IF;
 -- Ślady tej gry znikają razem z nią; pytania wracają do puli jako dostępne.
 DELETE FROM producer_question_history WHERE lang=p_lang AND game_id IN (p_id,coalesce(target,p_id));
 IF m.id IS NOT NULL THEN DELETE FROM market_games WHERE id=m.id; END IF;
 IF g.id IS NOT NULL THEN DELETE FROM producer_question_games WHERE id=g.id; END IF;
 FOR q IN SELECT value FROM jsonb_array_elements(p_questions) LOOP
  norm:=public.market_normalize_content(q->>'text');
  n:=CASE WHEN jsonb_typeof(q->'answers')='array' THEN jsonb_array_length(q->'answers') ELSE 0 END;
  bad:=length(coalesce(norm,''))<8 OR length(q->>'text')>500 OR n NOT BETWEEN 3 AND 6;
  IF NOT bad THEN
   FOR a IN SELECT value FROM jsonb_array_elements(q->'answers') LOOP
    IF length(btrim(coalesce(a->>'text','')))<1 OR length(a->>'text')>120 OR jsonb_typeof(a->'fixed_points') IS DISTINCT FROM 'number'
     OR (a->>'fixed_points')::numeric<>trunc((a->>'fixed_points')::numeric) OR (a->>'fixed_points')::numeric NOT BETWEEN 1 AND 100 THEN bad:=true; END IF;
   END LOOP;
  END IF;
  IF NOT bad THEN
   bad:=(SELECT count(DISTINCT market_normalize_content(value->>'text')) FROM jsonb_array_elements(q->'answers'))<>n
    OR (SELECT sum((value->>'fixed_points')::integer) FROM jsonb_array_elements(q->'answers'))>100
    OR jsonb_typeof(q->'embedding') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'embedding')<>384;
  END IF;
  IF bad THEN skipped:=skipped+1; CONTINUE; END IF;
  fp:=encode(sha256(convert_to(norm,'UTF8')),'hex');
  SELECT encode(sha256(convert_to(jsonb_agg(market_normalize_content(value->>'text') ORDER BY market_normalize_content(value->>'text'))::text,'UTF8')),'hex') INTO ak FROM jsonb_array_elements(q->'answers');
  av:=(q->'embedding')::text::public.vector(384);
  IF EXISTS(SELECT 1 FROM producer_question_pool x WHERE x.lang=p_lang AND (x.fingerprint=fp OR x.answer_key=ak)) OR
   EXISTS(SELECT 1 FROM producer_question_history h WHERE h.lang=p_lang AND (h.fingerprint=fp OR h.answer_key=ak)) OR
   EXISTS(SELECT 1 FROM market_game_questions x JOIN market_games mg ON mg.id=x.game_id WHERE mg.lang=p_lang AND mg.origin='producer' AND x.question_norm=norm) THEN
   duplicates:=duplicates+1; CONTINUE;
  END IF;
  q_origin:=CASE WHEN q->>'origin' IN ('search','generated') THEN q->>'origin' ELSE 'generated' END;
  src:=CASE WHEN jsonb_typeof(q->'source')='object' THEN q->'source' ELSE jsonb_build_object('points_origin','estimated') END;
  IF q_origin='search' AND coalesce(src->>'url','') !~ '^https?://' THEN q_origin:='generated'; END IF;
  INSERT INTO producer_question_pool(lang,text,answers,category_hint,origin,source,fingerprint,answer_key,embedding)
  VALUES(p_lang,q->>'text',q->'answers',left(coalesce(q->>'category_hint',''),300),q_origin,src||jsonb_build_object('from_game',left(coalesce(g_title,''),120)),fp,ak,av);
  restored:=restored+1;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'restored',restored,'skipped',skipped,'duplicates',duplicates);
END $$;


--
-- Name: qf_games_commit("uuid", "text", "text", "text", "jsonb", "jsonb", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_games_commit"("p_request" "uuid", "p_lang" "text", "p_mode" "text", "p_category" "text", "p_ids" "jsonb", "p_metadata" "jsonb", "p_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE total integer; qty integer; existing jsonb; meta jsonb; game uuid; item jsonb; questions jsonb; chosen uuid[]; i integer; n integer;
BEGIN
 IF p_lang NOT IN ('pl','en','uk') OR p_mode NOT IN ('manual','auto','category') OR p_count<10 THEN RAISE EXCEPTION 'invalid_game_request'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qf:'||p_lang,0));
 SELECT jsonb_agg(to_jsonb(g) ORDER BY created_at,id) INTO existing FROM producer_question_games g WHERE batch_id=p_request;
 IF existing IS NOT NULL THEN
  IF existing->0->>'lang'<>p_lang OR existing->0->>'mode'<>p_mode THEN RAISE EXCEPTION 'request_conflict'; END IF;
  RETURN existing;
 END IF;
 qty:=jsonb_array_length(p_metadata);total:=jsonb_array_length(p_ids);
 IF qty<1 OR total<>qty::bigint*p_count OR (p_mode='manual' AND qty<>1) OR (p_mode='category' AND length(btrim(p_category))=0) THEN RAISE EXCEPTION 'invalid_game_batch'; END IF;
 SELECT array_agg(value::uuid) INTO chosen FROM jsonb_array_elements_text(p_ids);
 IF (SELECT count(DISTINCT x) FROM unnest(chosen) x)<>total THEN RAISE EXCEPTION 'duplicate_selection'; END IF;
 PERFORM id FROM producer_question_pool WHERE id=ANY(chosen) AND lang=p_lang ORDER BY id FOR UPDATE;
 SELECT count(*) INTO n FROM producer_question_pool WHERE id=ANY(chosen) AND lang=p_lang;
 IF n<>total THEN RAISE EXCEPTION 'questions_unavailable'; END IF;
 FOR i IN 0..qty-1 LOOP
  meta:=p_metadata->i;
  IF length(btrim(coalesce(meta->>'title','')))=0 OR length(meta->>'title')>120 OR length(btrim(coalesce(meta->>'description','')))=0 THEN RAISE EXCEPTION 'missing_game_metadata'; END IF;
  SELECT jsonb_agg(jsonb_build_object('text',q.text,'answers',q.answers,'source',q.source,'origin',q.origin) ORDER BY ids.ord) INTO questions
   FROM unnest(chosen) WITH ORDINALITY ids(id,ord) JOIN producer_question_pool q ON q.id=ids.id WHERE ids.ord BETWEEN i*p_count+1 AND (i+1)*p_count;
  INSERT INTO producer_question_games(batch_id,lang,title,description,mode,category,payload)
   VALUES(p_request,p_lang,meta->>'title',meta->>'description',p_mode,coalesce(p_category,''),jsonb_build_object('title',meta->>'title','description',meta->>'description','questions',questions)) RETURNING id INTO game;
  INSERT INTO producer_question_history(lang,fingerprint,question_norm,answer_key,embedding,game_id)
   SELECT q.lang,q.fingerprint,market_normalize_content(q.text),q.answer_key,q.embedding,game FROM unnest(chosen) WITH ORDINALITY ids(id,ord)
   JOIN producer_question_pool q ON q.id=ids.id WHERE ids.ord BETWEEN i*p_count+1 AND (i+1)*p_count;
 END LOOP;
 DELETE FROM producer_question_pool WHERE id=ANY(chosen);
 SELECT jsonb_agg(to_jsonb(g) ORDER BY created_at,id) INTO existing FROM producer_question_games g WHERE batch_id=p_request;
 RETURN existing;
END $$;


--
-- Name: qf_is_known("text", "text", "text", "text", "public"."vector"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_is_known"("p_lang" "text", "p_norm" "text", "p_fp" "text", "p_ak" "text", "p_av" "public"."vector") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM producer_question_pool q WHERE q.lang=p_lang AND (q.fingerprint=p_fp OR q.answer_key=p_ak OR similarity(market_normalize_content(q.text),p_norm)>=0.88 OR 1-(q.embedding<=>p_av)>=0.94))
  OR EXISTS(SELECT 1 FROM producer_question_history h WHERE h.lang=p_lang AND (h.fingerprint=p_fp OR h.answer_key=p_ak OR similarity(h.question_norm,p_norm)>=0.88 OR 1-(h.embedding<=>p_av)>=0.94))
  OR EXISTS(SELECT 1 FROM market_game_questions q JOIN market_games g ON g.id=q.game_id WHERE g.lang=p_lang AND g.origin='producer' AND
   (q.question_norm=p_norm OR similarity(q.question_norm,p_norm)>=0.88 OR (q.embedding IS NOT NULL AND 1-(q.embedding<=>p_av)>=0.94)))
$$;


--
-- Name: qf_job_checkpoint("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_job_checkpoint"("p_id" "uuid", "p_lease" "uuid", "p_state" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 UPDATE producer_question_jobs SET
  status=CASE WHEN accepted>=target THEN 'completed' ELSE coalesce(p_state->>'status','queued') END,
  queries=coalesce(p_state->'queries',queries),cursor=coalesce((p_state->>'cursor')::integer,cursor),round=coalesce((p_state->>'round')::integer,round),
  rejected=rejected+coalesce((p_state->>'rejected')::integer,0),duplicates=duplicates+coalesce((p_state->>'duplicates')::integer,0),
  message=left(coalesce(p_state->>'message',''),500),next_run_at=now()+make_interval(secs=>greatest(2,coalesce((p_state->>'delay')::integer,5))),
  lease=NULL,lease_until=NULL,updated_at=now()
 WHERE id=p_id AND lease=p_lease AND status='running';
 RETURN FOUND;
END $$;


--
-- Name: qf_job_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_job_claim"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE job producer_question_jobs;
BEGIN
 SELECT * INTO job FROM producer_question_jobs WHERE status IN ('queued','running','waiting_budget','waiting_provider')
 AND accepted<target AND next_run_at<=now() AND (lease_until IS NULL OR lease_until<now())
 ORDER BY updated_at,id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE producer_question_jobs SET lease=gen_random_uuid(),lease_until=now()+interval '6 minutes',status='running',updated_at=now() WHERE id=job.id RETURNING * INTO job;
 RETURN to_jsonb(job);
END $$;


--
-- Name: qf_job_control("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_job_control"("p_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF p_action NOT IN ('pause','resume','cancel') THEN RETURN false; END IF;
 UPDATE producer_question_jobs SET status=CASE p_action WHEN 'pause' THEN 'paused' WHEN 'resume' THEN 'queued' ELSE 'cancelled' END,
 lease=NULL,lease_until=NULL,next_run_at=now(),updated_at=now(),message=''
 WHERE id=p_id AND status NOT IN ('completed','cancelled') AND (p_action<>'resume' OR status='paused');
 RETURN FOUND;
END $$;


--
-- Name: qf_job_create("uuid", "text", "text", integer, "text", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_job_create"("p_request" "uuid", "p_lang" "text", "p_kind" "text", "p_target" integer, "p_category" "text" DEFAULT ''::"text", "p_enrich" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE result producer_question_jobs;
BEGIN
 INSERT INTO producer_question_jobs(request_id,lang,kind,target,category,enrich) VALUES(p_request,p_lang,p_kind,p_target,btrim(p_category),p_enrich)
 ON CONFLICT(request_id) DO NOTHING;
 SELECT * INTO result FROM producer_question_jobs WHERE request_id=p_request;
 IF result.lang<>p_lang OR result.kind<>p_kind OR result.target<>p_target OR result.category<>btrim(p_category) OR result.enrich<>p_enrich THEN RAISE EXCEPTION 'request_conflict'; END IF;
 RETURN to_jsonb(result)-'lease'-'lease_until';
END $$;


--
-- Name: qf_known_questions("text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_known_questions"("p_lang" "text", "p_questions" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE q jsonb; i bigint; norm text; ak text; known jsonb:='[]';
BEGIN
 IF p_lang NOT IN ('pl','en','uk') OR jsonb_typeof(p_questions) IS DISTINCT FROM 'array' OR jsonb_array_length(p_questions)>50 THEN RAISE EXCEPTION 'invalid_request'; END IF;
 FOR q,i IN SELECT value,ordinality-1 FROM jsonb_array_elements(p_questions) WITH ORDINALITY LOOP
  norm:=public.market_normalize_content(q->>'text');
  CONTINUE WHEN length(coalesce(norm,''))<8 OR jsonb_typeof(q->'answers') IS DISTINCT FROM 'array'
   OR jsonb_typeof(q->'embedding') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'embedding')<>384;
  SELECT encode(sha256(convert_to(jsonb_agg(market_normalize_content(value->>'text') ORDER BY market_normalize_content(value->>'text'))::text,'UTF8')),'hex') INTO ak FROM jsonb_array_elements(q->'answers');
  IF qf_is_known(p_lang,norm,encode(sha256(convert_to(norm,'UTF8')),'hex'),ak,(q->'embedding')::text::public.vector(384)) THEN known:=known||to_jsonb(i); END IF;
 END LOOP;
 RETURN jsonb_build_object('known',known);
END $$;


--
-- Name: qf_offer("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_offer"("p_job" "uuid", "p_lease" "uuid", "p_question" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE job producer_question_jobs; norm text; fp text; ak text; av public.vector(384); a jsonb; n integer; qid uuid;
BEGIN
 SELECT * INTO job FROM producer_question_jobs WHERE id=p_job FOR UPDATE;
 IF NOT FOUND OR job.status<>'running' OR job.lease IS DISTINCT FROM p_lease OR job.accepted>=job.target THEN RETURN jsonb_build_object('ok',false,'reason','stopped'); END IF;
 IF p_question->>'lang' IS DISTINCT FROM job.lang OR p_question->>'origin' IS DISTINCT FROM job.kind THEN RAISE EXCEPTION 'invalid_question_context'; END IF;
 norm:=public.market_normalize_content(p_question->>'text');
 IF length(norm)<8 OR length(norm)>500 OR jsonb_typeof(p_question->'answers') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_question'; END IF;
 n:=jsonb_array_length(p_question->'answers');
 IF n<3 OR n>6 THEN RAISE EXCEPTION 'invalid_answers'; END IF;
 FOR a IN SELECT * FROM jsonb_array_elements(p_question->'answers') LOOP
  IF length(btrim(coalesce(a->>'text','')))<1 OR length(a->>'text')>120 OR jsonb_typeof(a->'fixed_points') IS DISTINCT FROM 'number' OR
   (a->>'fixed_points')::numeric<>trunc((a->>'fixed_points')::numeric) OR (a->>'fixed_points')::integer NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_answer'; END IF;
 END LOOP;
 IF (SELECT count(DISTINCT market_normalize_content(value->>'text')) FROM jsonb_array_elements(p_question->'answers'))<>n THEN RAISE EXCEPTION 'duplicate_answers'; END IF;
 IF (SELECT sum((value->>'fixed_points')::integer) FROM jsonb_array_elements(p_question->'answers'))>100 THEN RAISE EXCEPTION 'invalid_points'; END IF;
 IF jsonb_typeof(p_question->'source') IS DISTINCT FROM 'object' OR
  (job.kind='search' AND (coalesce(p_question->'source'->>'url','') !~ '^https?://' OR length(coalesce(p_question->'source'->>'evidence',''))<8)) OR
  (job.kind='generated' AND p_question->'source'->>'points_origin' IS DISTINCT FROM 'estimated') THEN RAISE EXCEPTION 'missing_provenance'; END IF;
 fp:=encode(sha256(convert_to(norm,'UTF8')),'hex');
 SELECT encode(sha256(convert_to(jsonb_agg(market_normalize_content(value->>'text') ORDER BY market_normalize_content(value->>'text'))::text,'UTF8')),'hex') INTO ak FROM jsonb_array_elements(p_question->'answers');
 av:=(p_question->'embedding')::text::public.vector(384);
 IF vector_norm(av)<0.5 THEN RAISE EXCEPTION 'invalid_embedding'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('qf:'||job.lang,0));
 IF qf_is_known(job.lang,norm,fp,ak,av) THEN RETURN jsonb_build_object('ok',false,'reason','duplicate'); END IF;
 INSERT INTO producer_question_pool(lang,text,answers,category_hint,origin,source,fingerprint,answer_key,embedding,job_id)
 VALUES(job.lang,p_question->>'text',p_question->'answers',left(coalesce(p_question->>'category_hint',''),300),job.kind,p_question->'source',fp,ak,av,job.id) RETURNING id INTO qid;
 UPDATE producer_question_jobs SET accepted=accepted+1,status=CASE WHEN accepted+1>=target THEN 'completed' ELSE status END,updated_at=now() WHERE id=job.id;
 RETURN jsonb_build_object('ok',true,'id',qid);
END $$;


--
-- Name: qf_publish("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_publish"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE g producer_question_games; result uuid;
BEGIN
 SELECT * INTO g FROM producer_question_games WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'game_not_found'; END IF;
 IF g.published_id IS NOT NULL THEN
  UPDATE market_games SET status='published' WHERE id=g.published_id AND origin='producer';
  RETURN jsonb_build_object('ok',true,'id',g.published_id);
 END IF;
 INSERT INTO market_games(title,description,lang,payload,origin,status) VALUES(g.title,g.description,g.lang,g.payload,'producer','published') RETURNING id INTO result;
 UPDATE producer_question_games SET published_id=result WHERE id=p_id;
 RETURN jsonb_build_object('ok',true,'id',result);
END $$;


--
-- Name: qf_unpublish("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."qf_unpublish"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 UPDATE market_games SET status='withdrawn' WHERE id=(SELECT published_id FROM producer_question_games WHERE id=p_id) AND origin='producer';
 RETURN FOUND;
END $$;


--
-- Name: questions_rules_state_stmt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."questions_rules_state_stmt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ids uuid[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct game_id) into v_ids from new_rows;
  elsif tg_op = 'DELETE' then
    select array_agg(distinct game_id) into v_ids from old_rows;
  else
    select array_agg(distinct game_id) into v_ids
    from (select game_id from new_rows union select game_id from old_rows) x;
  end if;
  if v_ids is not null then
    perform public.games_rules_state_refresh(v_ids);
  end if;
  return null;
end;
$$;


--
-- Name: release_edit_lock("text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."release_edit_lock"("p_resource_type" "text", "p_resource_id" "uuid", "p_tab_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  delete from public.edit_locks
  where resource_type = p_resource_type
    and resource_id = p_resource_id
    and holder_tab_id = p_tab_id
    and holder_user_id = auth.uid();  -- 479: tylko własne

  -- 522: koniec użycia — czekająca aktualizacja demo, jeśli zasób jest już wolny.
  perform public._demo_apply_pending(p_resource_type, p_resource_id);

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: release_edit_locks("jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."release_edit_locks"("p_resources" "jsonb", "p_tab_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT DISTINCT x->>'type' AS type, (x->>'id')::uuid AS id
             FROM jsonb_array_elements(coalesce(p_resources, '[]'::jsonb)) x LOOP
    PERFORM public.release_edit_lock(r.type, r.id, p_tab_id);
  END LOOP;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: rename_resource_checked("text", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rename_resource_checked"("p_resource_type" "text", "p_resource_id" "uuid", "p_name" "text", "p_tab_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_name text := trim(coalesce(p_name, ''));
  v_blocker public.edit_locks;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated');
  end if;
  if v_name = '' then
    return jsonb_build_object('ok', false, 'error', 'invalid_name');
  end if;

  if p_resource_type = 'game' then
    if not exists (select 1 from public.games where id = p_resource_id and owner_id = v_uid) then
      return jsonb_build_object('ok', false, 'error', 'not_found_or_forbidden');
    end if;
    select * into v_blocker from public.edit_lock_blockers('game', p_resource_id, 'exclusive', p_tab_id) limit 1;
    if found then
      return jsonb_build_object('ok', false, 'in_use', true, 'reason', 'locked');
    end if;
    update public.games set name = v_name where id = p_resource_id and owner_id = v_uid;

  elsif p_resource_type = 'base' then
    if not exists (select 1 from public.question_bases where id = p_resource_id and owner_id = v_uid) then
      return jsonb_build_object('ok', false, 'error', 'not_found_or_forbidden');
    end if;
    select * into v_blocker from public.edit_lock_blockers('base', p_resource_id, 'exclusive', p_tab_id) limit 1;
    if found then
      return jsonb_build_object('ok', false, 'in_use', true, 'reason', 'locked');
    end if;
    update public.question_bases set name = v_name, updated_at = now()
     where id = p_resource_id and owner_id = v_uid;

  elsif p_resource_type = 'logo' then
    return public.update_logo_checked(p_resource_id, jsonb_build_object('name', v_name), p_tab_id);

  else
    return jsonb_build_object('ok', false, 'error', 'unknown_resource_type');
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: request_display_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."request_display_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP = 'INSERT' OR NEW.step IS DISTINCT FROM OLD.step OR
    NEW.sound_cue_seq IS DISTINCT FROM OLD.sound_cue_seq THEN
  INSERT INTO public.game_state_display_completion(game_id, requested_rev, requested_at)
  VALUES(NEW.game_id, NEW.rev, clock_timestamp())
  ON CONFLICT(game_id) DO UPDATE
    SET requested_rev = excluded.requested_rev, requested_at = excluded.requested_at;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: reserved_username_prefixes_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reserved_username_prefixes_list"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('prefix',prefix,'kind',kind) ORDER BY prefix),'[]'::jsonb)
 FROM public.reserved_username_prefixes;
$$;


--
-- Name: reserved_username_reason("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reserved_username_reason"("p_username" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
 SELECT kind FROM public.reserved_username_prefixes
 WHERE starts_with(lower(btrim(p_username)),prefix) ORDER BY length(prefix) DESC LIMIT 1;
$$;


--
-- Name: reset_email_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reset_email_limits"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_share numeric := coalesce((select queue_share_pct from public.mail_settings where id = 1), 80) / 100.0;
begin
  update public.email_providers
  set rem_worker = floor(daily_limit * v_share),
      rem_immediate = daily_limit - floor(daily_limit * v_share)
  where is_active = true;
end;
$$;


--
-- Name: resolve_device_connect_code("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resolve_device_connect_code"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_rec record;
  v_live boolean;
BEGIN
  DELETE FROM public.device_connect_codes
  WHERE expires_at IS NOT NULL AND expires_at < now();

  IF coalesce(p_code, '') !~ '^[0-9]{6}$' THEN
    RETURN jsonb_build_object('ok', false, 'err', 'not_found');
  END IF;

  SELECT dcc.*, p.username AS owner_username
  INTO v_rec
  FROM public.device_connect_codes dcc
  JOIN public.profiles p ON p.id = dcc.owner_id
  WHERE dcc.code = p_code;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'err', 'not_found');
  END IF;

  IF v_rec.device_type = 'poll_qr' THEN
    v_live := EXISTS (SELECT 1 FROM public.games g
                      WHERE g.id = v_rec.game_id AND g.owner_id = v_rec.owner_id
                        AND g.status IN ('poll_open', 'poll_stopped') AND g.share_key_poll = v_rec.share_key);
  ELSE
    v_live := public.control_device_key_valid(v_rec.game_id, v_rec.device_type, v_rec.share_key);
  END IF;
  IF NOT v_live THEN
    DELETE FROM public.device_connect_codes WHERE id = v_rec.id;
    RETURN jsonb_build_object('ok', false, 'err', 'not_found');
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'code',           v_rec.code,
    'device_type',    v_rec.device_type,
    'game_id',        v_rec.game_id,
    'game_name',      v_rec.game_name,
    'share_key',      v_rec.share_key,
    'owner_username', v_rec.owner_username
  );
END;
$_$;


--
-- Name: resource_copy_badges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resource_copy_badges"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); items jsonb;
BEGIN
 IF actor IS NULL OR NOT public._poll_identity_regular(actor,(SELECT to_jsonb(u) FROM auth.users u WHERE u.id=actor)) THEN
  RETURN jsonb_build_object('ok',false,'items','[]'::jsonb);
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('kind',resource_kind,'variant',variant,'mode',mode,'count',n)),'[]'::jsonb)
 INTO items FROM (SELECT o.resource_kind,o.variant,
   CASE WHEN o.resource_kind='logo' THEN CASE WHEN l.type='GLYPH_30x10' THEN 'TEXT' ELSE coalesce(l.payload#>>'{source,mode}','DRAW') END END mode,
   count(*)::integer n FROM public.resource_copy_offers o LEFT JOIN public.user_logos l ON l.id=o.logo_id
  WHERE o.recipient_id=actor AND o.status='pending' AND o.created_at+interval '5 days'>clock_timestamp()
  GROUP BY o.resource_kind,o.variant,mode) counts;
 RETURN jsonb_build_object('ok',true,'items',items);
END $$;


--
-- Name: resource_copy_decide("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resource_copy_decide"("p_offer" "uuid", "p_decision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE identity jsonb;
BEGIN
 SELECT to_jsonb(u) INTO identity FROM auth.users u WHERE u.id=auth.uid();
 IF NOT public._account_is_registered(auth.uid(),identity) THEN
  RETURN jsonb_build_object('ok',false,'error','auth_required');
 END IF;
 RETURN public._copy_decide(p_offer,p_decision);
END $$;


--
-- Name: resource_copy_go_resolve("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resource_copy_go_resolve"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE item public.resource_copy_offers; actor uuid:=auth.uid(); recipient_email text; recipient_label text;
BEGIN
 SELECT * INTO item FROM public.resource_copy_offers WHERE token=p_token FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','invalid_token'); END IF;
 IF item.status='pending' AND item.created_at+interval '5 days'<=clock_timestamp() THEN
  PERFORM public._copy_discard(item.id,'expired');
  SELECT * INTO item FROM public.resource_copy_offers WHERE id=item.id;
 END IF;
 SELECT public._norm_email(u.email),coalesce(nullif(p.username,''),public._norm_email(u.email)) INTO recipient_email,recipient_label
  FROM auth.users u LEFT JOIN public.profiles p ON p.id=u.id WHERE u.id=item.recipient_id;
 RETURN jsonb_build_object('ok',true,'kind','copy','id',item.id,'status',item.status,'resource_kind',item.resource_kind,
  'name',item.name,'sender_label',item.sender_label,'recipient_email',recipient_email,
  'recipient_matches_me',actor=item.recipient_id,'recipient_label',recipient_label,
  'expires_at',item.created_at+interval '5 days');
END $$;


--
-- Name: resource_copy_history("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resource_copy_history"("p_kind" "text", "p_source" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); identity jsonb; items jsonb;
BEGIN
 SELECT to_jsonb(u) INTO identity FROM auth.users u WHERE u.id=actor;
 IF NOT public._account_is_registered(actor,identity) THEN
  RETURN jsonb_build_object('ok',false,'error','auth_required','items','[]'::jsonb);
 END IF;
 IF p_kind='game' AND NOT EXISTS(SELECT 1 FROM public.games WHERE id=p_source AND owner_id=actor)
  OR p_kind='logo' AND NOT EXISTS(SELECT 1 FROM public.user_logos WHERE id=p_source AND user_id=actor)
  OR p_kind NOT IN('game','logo') THEN RAISE EXCEPTION 'not_found'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('recipient_label',h.recipient_label,'sent_at',h.sent_at)
   ORDER BY h.sent_at DESC),'[]'::jsonb) INTO items FROM public.resource_copy_history h
  WHERE h.sender_id=actor AND h.sent_at>clock_timestamp()-interval '30 days'
   AND CASE p_kind WHEN 'game' THEN h.game_id ELSE h.logo_id END=p_source;
 RETURN jsonb_build_object('ok',true,'items',items);
END $$;


--
-- Name: resource_copy_inbox("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."resource_copy_inbox"("p_kind" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); items jsonb;
BEGIN
 IF actor IS NULL OR NOT public._poll_identity_regular(actor,(SELECT to_jsonb(u) FROM auth.users u WHERE u.id=actor)) THEN
  RETURN jsonb_build_object('ok',false,'error','auth_required','items','[]'::jsonb);
 END IF;
 IF p_kind IS NOT NULL AND p_kind NOT IN('game','logo') THEN RAISE EXCEPTION 'invalid_copy_kind'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'resource_kind',o.resource_kind,'variant',o.variant,
  'logo_mode',CASE WHEN o.resource_kind='logo' THEN (SELECT CASE WHEN l.type='GLYPH_30x10' THEN 'TEXT' ELSE l.payload#>>'{source,mode}' END FROM public.user_logos l WHERE l.id=o.logo_id) END,
  'name',o.name,'sender_label',o.sender_label,'created_at',o.created_at,'expires_at',o.created_at+interval '5 days',
  'game_id',o.game_id,'logo_id',o.logo_id) ORDER BY o.created_at DESC),'[]'::jsonb)
 INTO items FROM public.resource_copy_offers o WHERE o.recipient_id=actor AND o.status='pending'
  AND o.created_at+interval '5 days'>clock_timestamp() AND (p_kind IS NULL OR o.resource_kind=p_kind);
 RETURN jsonb_build_object('ok',true,'items',items);
END $$;


