--
-- Name: stats_excluded_users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."stats_excluded_users" (
    "user_id" "uuid" NOT NULL,
    "added_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


--
-- Name: stats_exclusions_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."stats_exclusions_effective" AS
 SELECT DISTINCT ON ("user_id") "user_id",
    "added_at",
    "reason"
   FROM ( SELECT "stats_excluded_users"."user_id",
            "stats_excluded_users"."added_at",
            'manual'::"text" AS "reason",
            2 AS "priority"
           FROM "public"."stats_excluded_users"
        UNION ALL
         SELECT "p"."id",
            "p"."created_at",
                CASE
                    WHEN (COALESCE(("u"."raw_app_meta_data" ->> 'is_test_guest'::"text"), 'false'::"text") = 'true'::"text") THEN 'test_guest'::"text"
                    WHEN ("i"."role" IS NOT NULL) THEN ('test:'::"text" || "i"."role")
                    ELSE ('test:'::"text" || ("u"."raw_app_meta_data" ->> 'e2e_role'::"text"))
                END AS "case",
            1
           FROM (("public"."profiles" "p"
             JOIN "auth"."users" "u" ON (("u"."id" = "p"."id")))
             LEFT JOIN LATERAL ( SELECT "ei"."role"
                   FROM "public"."e2e_identities" "ei"
                  WHERE (("ei"."user_id" = "u"."id") OR (("ei"."email" IS NOT NULL) AND (("lower"(("u"."email")::"text") = "ei"."email") OR ("lower"(("u"."email")::"text") = "replace"("ei"."email", '@'::"text", '.new@'::"text")))))
                  ORDER BY ("ei"."user_id" = "u"."id") DESC NULLS LAST
                 LIMIT 1) "i" ON (true))
          WHERE ((COALESCE(("u"."raw_app_meta_data" ->> 'is_test_guest'::"text"), 'false'::"text") = 'true'::"text") OR (("u"."raw_app_meta_data" ->> 'e2e_role'::"text") IS NOT NULL) OR ("i"."role" IS NOT NULL))) "x"
  ORDER BY "user_id", "priority";


