  WHERE (("c"."id" = "qb_category_tags"."category_id") AND ("t"."id" = "qb_category_tags"."tag_id") AND (("b"."owner_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
           FROM "public"."question_base_shares" "s"
